  ui_story_5037_50370501_35_dialog_content = "ฉันไม่คิดว่าฉันได้ยินจากคุณ วิค?",
  ui_story_5037_50370501_36_dialog_content = "ทำไมเราไม่ลืมมัน",
  ui_story_5037_50370501_37_dialog_content = "ในเมื่อผมแพ้ คุณก็ควรให้ผมกลับบ้านได้แล้ว!",
