  ui_story_5037_50370501_40_dialog_content = "บอกฉันสิ Lady Sheol!",
  ui_story_5037_50370501_41_dialog_content = "นี่คือวิธีที่คุณเขียนบทใช่ไหม?",
  ui_story_5037_50370501_42_dialog_content = "สคริปต์สำหรับรายการเรียลลิตี้?",
  ui_story_5037_50370501_43_dialog_content = "คุณเป็นอัจฉริยะ Fia",
  ui_story_5037_50370501_44_dialog_content = "แน่นอนฉัน! ฮิฮิ.",
