  ui_story_5037_50370501_48_dialog_content = "อย่างไรก็ตาม Fia ผลลัพธ์ของรอบนี้เป็นของแท้",
  ui_story_5037_50370501_49_dialog_content = "หากคุณยังมีข้อสงสัย อย่าลังเลที่จะชมการแสดงซ้ำของคอนเสิร์ต",
  ui_story_5037_50370501_50_dialog_content = "มาคุยกับฉันได้ทุกเมื่อหากคุณมีคำถามในภายหลัง",
  ui_story_5037_50370501_51_dialog_content = "<color=#828282>ในเวลาต่อมา</color>",
  ui_story_5037_50370501_52_dialog_content = "พวกเขาทำอย่างนั้นได้อย่างไร? พวกเขาดึงเคล็ดลับออกมาได้อย่างไร!",
  ui_story_5037_50370501_53_dialog_content = "โกลดี้เปลี่ยนชุดในเสี้ยววินาที!?",
  ui_story_5037_50370501_54_dialog_content = "และปรากฏตัวขึ้นจากอากาศบาง ๆ ในหมู่ผู้ชมจากนั้นก็บินกลับไปที่เวที?",
