  ui_story_5037_50370501_57_dialog_content = "เอ่อ อะแฮ่ม",
  ui_story_5037_50370501_58_dialog_content = "ในที่สุดคุณก็ได้รับมันแล้ว? แม้ว่าฉันจะมีความสามารถมากมาย แต่ฉันก็ยังเทียบไม่ได้กับไอดอลมืออาชีพ",
  ui_story_5037_50370501_59_dialog_content = "ยังไม่เร็วเกินไปที่จะยอมรับในตอนนี้ ฉันจะไปเก็บของ",
  ui_story_5037_50370501_60_dialog_content = "อย่าหนีนะ!",
  ui_story_5037_50370501_61_dialog_content = "ฉันรู้แม้ไม่บอก...",
  ui_story_5037_50370501_62_dialog_content = "ไม่ใช่ความผิดของคุณที่เราแพ้",
