  ui_story_5037_50370701_156_dialog_content = "นั่นคือสิ่งที่คุณเห็น",
  ui_story_5037_50370701_157_dialog_content = "แฟน ๆ จำนวนมากชื่นชมการออกแบบเวที ทำไมคุณไม่ไปคลุกคลีกับพวกเขา",
  ui_story_5037_50370701_158_dialog_content = "เรื่องนั้น ฉัน...",
