  ui_story_5037_50370701_205_dialog_content = "หา?",
  ui_story_5037_50370701_206_dialog_content = "อย่างไรก็ตาม คุณมาจากไหน PlayerName?",
  ui_story_5037_50370701_207_dialog_content = "อยู่ดีๆประตูก็เปิดออกฉันจึงเดินเข้าไป",
