  ui_story_5037_50370701_217_dialog_content = "แปดสิบสาม แปดสิบสี่ แปดสิบห้า...",
  ui_story_5037_50370701_218_dialog_content = "Fia จะไม่มีอีกแล้ว ไม่ว่าคุณจะนับกี่ครั้งก็ตาม",
  ui_story_5037_50370701_219_dialog_content = "นอกจากนี้ คุณไม่คิดว่าคุณควรตรวจสอบเจ้านายของคุณหรือ? เพียงแค่มองไปที่เขา",
  ui_story_5037_50370701_220_dialog_content = "Kyllo ลากเขาออกมาจากใต้โต๊ะ แต่เขายังไม่ตื่น!",
  ui_story_5037_50370701_221_dialog_content = "รอสักครู่! ฉันจะไปหาคุณเมื่อฉันนับถึงร้อย...",
