  ui_story_5037_50370701_228_dialog_content = "แม้ว่าฉันจะคิดว่ามันเป็นเรื่องปกติสำหรับคนที่ไม่เคยทำงานเลยสักครั้งในชีวิต!",
  ui_story_5037_50370701_229_dialog_content = "รัวๆๆๆๆๆ!!!",
  ui_story_5037_50370701_230_dialog_content = "เฮ้ วิค? ตอนนี้คุณตื่นหรือยัง",
  ui_story_5037_50370701_231_dialog_content = "PlayerName? คุณมาทำอะไรที่นี่?!",
  ui_story_5037_50370701_232_dialog_content = "วิ่ง! Kyllo กลายเป็นบ้าไปแล้ว! มันบังคับให้ฉันฝึกฝน!",
