  ui_story_5037_50370701_238_dialog_content = "เอ่อ เฟีย? เราจะโน้มน้าววิคได้อย่างไรว่าเขาไม่ได้ฝันไป?",
  ui_story_5037_50370701_239_dialog_content = "ฮี่ฮี่ฮี่ ดูเหมือนว่าถึงเวลาที่ Kyllo จะเปล่งประกายอีกครั้ง! รับเขา!",
  ui_story_5037_50370701_240_dialog_content = "!!!",
  ui_story_5037_50370701_241_dialog_content = "N-เดี๋ยวก่อน Fia! เจ้านายของคุณตื่นแล้ว ฉันสาบาน!",
