  ui_story_5037_50370701_244_dialog_content = "Lady Sheol เป็นคนใจกว้างจริง ๆ เหรอ?",
  ui_story_5037_50370701_245_dialog_content = "ทั้งหมดที่เราทำก็แค่เข้าร่วมรายการเรียลลิตี้ของเธอสองสามวัน และเธอก็จ่าย Nightium ให้เรามากเป็นการตอบแทน...",
  ui_story_5037_50370701_246_dialog_content = "ฉันสงสัยว่าไอดอลที่แท้จริงทำเงินได้เท่าไหร่?",
  ui_story_5037_50370701_247_dialog_content = "ทำไมคุณสนใจว่าคนอื่นทำเงินได้เท่าไหร่ Fia? เราควรพอใจกับสิ่งที่เรามีอยู่แล้วใช่ไหม?",
