  ui_story_5037_50370701_249_dialog_content = "ไม่ค่อยได้ยินคุณพูดอะไรจริงจังซักครั้ง...",
  ui_story_5037_50370701_250_dialog_content = "ไร้สาระ ฉันเป็นแบบนี้ตลอด! ตอนนี้ ถ้าคุณจะขอโทษ มีโต๊ะในบุฟเฟ่ต์ Umbraton ใหม่ที่มีชื่อของฉันอยู่!",
