  ui_story_5037_50370701_252_dialog_content = "อะไร ทำไมจะไม่ล่ะ?!",
  ui_story_5037_50370701_253_dialog_content = "ในช่วงสองสามวันที่ผ่านมา ฉันไม่ได้ทำอะไรนอกจากรับฟังข้อเรียกร้องไร้สาระของคุณ!",
  ui_story_5037_50370701_254_dialog_content = "ถ้าฉันไม่ออกกำลังกาย ฉันกำลังดูน้ำหนัก ฉันจำไม่ได้ด้วยซ้ำว่าครั้งสุดท้ายที่ฉันทานอาหารดีๆ มื้อไหน!",
  ui_story_5037_50370701_255_dialog_content = "เงินเราไม่ได้เข้าทุกวันนะรู้ยัง? เราควรรักษาตัวเองเมื่อมีโอกาส!",
  ui_story_5037_50370701_256_dialog_content = "ดูเหมือนคุณยังไม่เข้าใจสถานการณ์ของเราดีนัก มาสเตอร์",
  ui_story_5037_50370701_257_dialog_content = "นี่อาจดูเหมือนเงินจำนวนมากในแวบแรก",
  ui_story_5037_50370701_258_dialog_content = "แต่เมื่อคุณคำนึงถึงค่าขนม Drakolion ค่าอาหารตามปกติ ค่าซ่อมแซมบ้าน และค่าจ้างทำงานของฉัน...",
  ui_story_5037_50370701_259_dialog_content = "ที่ผลาญเงินไปกว่าครึ่ง!",
  ui_story_5037_50370701_260_dialog_content = "และเมื่อเราพิจารณาว่าคุณจะเป็นแหล่งรายได้ที่ไม่น่าเชื่อถือเพียงใด...",
  ui_story_5037_50370701_261_dialog_content = "ฉันไม่รู้หรอกว่าเงินก้อนนี้จะอยู่กับเราไปนานแค่ไหน!",
  ui_story_5037_50370701_262_dialog_content = "เดี๋ยวก่อนคุณหมายถึงอะไรเกี่ยวกับรายได้ของเขา?",
  ui_story_5037_50370701_263_dialog_content = "Vic มีศักยภาพมากในฐานะไอดอล! ทำไมเขาไม่ทำต่อล่ะ?",
  ui_story_5037_50370701_264_dialog_content = "ช่วยฉันด้วย PlayerName.",
  ui_story_5037_50370701_265_dialog_content = "การที่ฉันอยู่ได้หลายวันขนาดนี้ไม่ใช่เรื่องมหัศจรรย์เลย และคุณต้องการให้ฉันทำอย่างนั้นไปตลอดชีวิตหรือไม่?",
  ui_story_5037_50370701_266_dialog_content = "แค่คิดก็ฝันร้ายแล้ว",
  ui_story_5037_50370701_267_dialog_content = "PlayerName ถูกต้องอย่างยิ่ง อาจารย์!",
  ui_story_5037_50370701_268_dialog_content = "คุณใช้เวลาทั้งหมดที่บ้านแทนที่จะหางานทำ และคุณไม่ได้ดูแลสัตว์มหัศจรรย์ให้ดีด้วยซ้ำ...",
  ui_story_5037_50370701_269_dialog_content = "คุณอาจใช้ตัวเองเป็นไอดอล",
  ui_story_5037_50370701_270_dialog_content = "แล้วใครจะรู้ล่ะ? เมื่อรายการเรียลลิตี้ออกอากาศ คุณอาจมีแฟนๆ มากขึ้นกว่าเดิม อาจารย์!",
  ui_story_5037_50370701_271_dialog_content = "โอ้ที่รัก เฟียน้อย...",
  ui_story_5037_50370701_272_dialog_content = "เลิกยุ่งกับนายสักทีดีมั้ย!",
  ui_story_5037_50370701_273_dialog_content = "ไม่! คุณจะเป็นไอดอลที่ยิ่งใหญ่และประสบความสำเร็จ และคุณจะต้องชอบมัน!",
  ui_story_5037_50370701_274_dialog_content = "อะไร—?!",
  ui_story_5037_50370701_275_dialog_content = "ดูสิ เรายังพอมีเวลาเหลือให้ฝึกอีก! ไปกันเถอะมาสเตอร์!",
  ui_story_5037_50370701_276_dialog_content = "B-แต่ฉันไม่อยากฝึกต่อแล้ว... ฉันหมดแรงแล้ว...",
  ui_story_5037_50370701_277_dialog_content = "โอ้ คิลโล่? ฉันคิดว่าเจ้านายของเราต้องการแรงจูงใจเล็กน้อย",
  ui_story_5037_50370701_278_dialog_content = "นู๋—!",
  ui_story_5037_50370701_279_dialog_content = "เฮ้อ... ฉันไม่เคยเห็นอาจารย์วิ่งเร็วขนาดนี้มาก่อนในชีวิต",
  ui_story_5037_50370701_280_dialog_content = "มากสำหรับการ \"หมดแรง\" เหรอ? เฮ้! หากคุณมีพลังงานเพียงพอที่จะวิ่งหนี คุณก็ยังมีพลังงานเพียงพอที่จะฝึกฝน!",
  ui_story_5037_50370701_281_dialog_content = "วิก...",
  ui_story_5037_50370701_282_dialog_content = "อดทนหน่อย!",
  ui_story_5037_50370701_283_dialog_content = "\"Best Producer\" เอ๊ะ...?",
  ui_story_5037_50370701_284_dialog_content = "ฮี่ฮี่... ฉันรู้ว่าฉันไม่ควรปล่อยให้รางวัลของ Lady Sheol อยู่ในหัวของฉัน",
  ui_story_5037_50370701_285_dialog_content = "เมื่อนึกย้อนไปถึงวันแรกที่ฉันมาถึง Starlit Agency ฉันก็ไม่รู้ว่าตัวเองกำลังทำอะไรอยู่ ฉันกังวลว่าจะทำให้ชีวิตของโกลดี้ลำบากกว่าเดิม",
  ui_story_5037_50370701_286_dialog_content = "แต่ฉันสามารถช่วย Goldie ในคอนเสิร์ตทั้งสามของเธอได้ และยังทำให้ Lady Sheol ยอมรับฉันอีกด้วย!",
  ui_story_5037_50370701_287_dialog_content = "ฉันรอไม่ไหวแล้วที่จะทำให้ไวซ์กับคาร์ลีนประหลาดใจด้วยเรื่องนี้",
  ui_story_5037_50370701_288_dialog_content = "พวกเขาควรจะอยู่ที่ไหนสักแห่งในบริเวณใกล้เคียงใช่ไหม?",
  ui_story_5037_50370701_289_dialog_content = "ฉันสงสัยว่าพวกเขาอยู่ในห้องนี้หรือไม่?",
  ui_story_5037_50370701_290_dialog_content = "<color=#828282>ก๊อกก๊อก!</color>",
  ui_story_5037_50370701_291_dialog_content = "ขอโทษผู้บุกรุก!",
  ui_story_5037_50370701_292_dialog_content = "ตลกดี... ปกติไฟในห้องนี้จะเปิดอยู่ ทำไมวันนี้ที่นี่มืดจัง",
  ui_story_5037_50370701_293_dialog_content = "รอง? คาร์ลีน? หึ เดาว่าพวกเขาไม่ได้อยู่ที่นี่แล้ว",
  ui_story_5037_50370701_294_dialog_content = "<color=#828282>แคว่ก!</color>",
  ui_story_5037_50370701_295_dialog_content = "หา?!",
  ui_story_5037_50370701_296_dialog_content = "เซอร์ไพรส์!!!",
  ui_story_5037_50370701_297_dialog_content = "ขอแสดงความยินดีกับการจัดคอนเสิร์ตจบการศึกษาที่สมบูรณ์แบบ!",
  ui_story_5037_50370701_298_dialog_content = "และขอแสดงความยินดีที่ทำภารกิจสำเร็จ PlayerName.",
  ui_story_5037_50370701_299_dialog_content = "อะ-อะไรกันเนี่ย...?",
  ui_story_5037_50370701_300_dialog_content = "คัดสรรอาหารและเครื่องดื่มที่ดีที่สุดจากบุฟเฟ่ต์ระดับไฮเอนด์ที่เพิ่งเปิดใหม่ใน Umbraton",
  ui_story_5037_50370701_301_dialog_content = "แล้วก็—เค้กมหึมาก้อนนี้ด้วย! ดูน่าอร่อยใช่มั้ยล่ะ?",
  ui_story_5037_50370701_302_dialog_content = "ตั้งแต่คุณเริ่มฝึกเป็นโปรดิวเซอร์ คุณก็ไม่ได้กินดีอยู่ดี",
  ui_story_5037_50370701_303_dialog_content = "ซู่... เราตัดสินใจที่จะจัดงานฉลองเล็กๆ น้อยๆ เพื่อคุณโดยเฉพาะ PlayerName! ดู? มีรายการโปรดทั้งหมดของคุณ!",
  ui_story_5037_50370701_304_dialog_content = "รอง คาร์ลีน...",
  ui_story_5037_50370701_305_dialog_content = "คุณสองคนวางแผนเรื่องนี้มานานแค่ไหนแล้ว?",
  ui_story_5037_50370701_306_dialog_content = "ฉันไม่รู้เลย!",
  ui_story_5037_50370701_307_dialog_content = "ฮิฮิ! จริง ๆ แล้ว เราคิดขึ้นมาได้สักพักแล้ว",
  ui_story_5037_50370701_308_dialog_content = "และด้วยความที่คุณยุ่งมากในวันนี้ เราจึงมีเวลาเตรียมตัวมากมาย",
  ui_story_5037_50370701_309_dialog_content = "แปลว่าคุณสองคนรู้ผลคอนเสิร์ตวันนี้?",
  ui_story_5037_50370701_310_dialog_content = "ไม่! เราหวังว่าคุณจะบอกเรา",
  ui_story_5037_50370701_311_dialog_content = "เอ่อ... คุณจะทำอย่างไรถ้าเราแพ้? เรายังมีเหตุผลที่จะเฉลิมฉลองหรือไม่?",
  ui_story_5037_50370701_312_dialog_content = "ผมกับรองตกลงกันแล้วว่าไม่ว่าผลวันนี้จะเป็นอย่างไร",
  ui_story_5037_50370701_313_dialog_content = "การทำงานหนักทั้งหมดของคุณมีเหตุผลเพียงพอที่จะเฉลิมฉลอง",
  ui_story_5037_50370701_314_dialog_content = "ไม่เพียงแต่คุณศึกษาใจของคุณ PlayerName. คุณติดกับมันจนถึงที่สุด! นั่นเป็นความสำเร็จที่ยิ่งใหญ่ในสายตาของฉัน!",
  ui_story_5037_50370701_315_dialog_content = "นั่นเป็นเหตุผลที่เราจะปาร์ตี้ไม่ว่าจะเกิดอะไรขึ้น!",
  ui_story_5037_50370701_316_dialog_content = "ย-พวกนาย... อร๊าย ทำไมนายต้องน่ารักขนาดนี้ด้วย!",
  ui_story_5037_50370701_317_dialog_content = "ดู? ตอนนี้ฉันมีบางอย่างเข้าตา ขอบคุณนะ!",
  ui_story_5037_50370701_318_dialog_content = "แล้ววันนี้ใครชนะ?",
  ui_story_5037_50370701_319_dialog_content = "ฉันคิดว่าคุณบอกว่ามันไม่สำคัญ?!",
  ui_story_5037_50370701_320_dialog_content = "ฮ่าฮ่าฮ่า! นั่นเป็นเพราะเราเชื่อใจคุณ PlayerName!",
  ui_story_5037_50370701_321_dialog_content = "นอกจากนี้ คุณพึมพำบางอย่างเกี่ยวกับสิ่งที่คุณอยากบอกเราเมื่อคุณอยู่ข้างนอก แล้วมันคืออะไร?",
  ui_story_5037_50370701_322_dialog_content = "ฮี่ฮี่ฮี่ คาดเดาอะไร โกลดี้กับฉันชนะวันนี้!",
  ui_story_5037_50370701_323_dialog_content = "และไม่เพียงเท่านั้น Lady Sheol ยังมอบรางวัล Best Producer ให้ฉันด้วย!",
  ui_story_5037_50370701_324_dialog_content = "ว้าว! ฉันไม่รู้ด้วยซ้ำว่าพวกเขาได้รับรางวัลสำหรับสิ่งนั้น!",
  ui_story_5037_50370701_325_dialog_content = "ดูเหมือนว่า Lady Sheol มีสายตาที่ค่อนข้างเฉียบแหลม ฉันไม่คิดว่าความก้าวหน้าที่น่าทึ่งของคุณจะหายไปจากเธอเลย PlayerName.",
  ui_story_5037_50370701_326_dialog_content = "รางวัลนี้มาพร้อมกับเงินรางวัลหรือไม่? ฮะ? ฮะ?!",
  ui_story_5037_50370701_327_dialog_content = "ฉัน เอ่อ... ไม่คิดอย่างนั้น",
  ui_story_5037_50370701_328_dialog_content = "ฮี่ฮี่ เข้าท่าดี ท้ายที่สุดแล้ว ไม่มีเงินมากมายเทียบได้กับเกียรติยศของการได้รับรางวัลนั้น จริงไหม?",
  ui_story_5037_50370701_329_dialog_content = "เห็นด้วย คุณควรมีเวลาหางานทำได้ง่ายขึ้นในอนาคตด้วย",
  ui_story_5037_50370701_330_dialog_content = "ถูกตัอง! โดยพื้นฐานแล้วคุณอยู่ในระดับเดียวกับโปรดิวเซอร์มืออาชีพคนอื่นๆ แล้วตอนนี้!",
  ui_story_5037_50370701_331_dialog_content = "แต่ถ้าไม่ใช่เพราะพวกคุณคอยช่วยเหลือฉันตลอดเวลา ฉันคงไม่มีทางมั่นใจที่จะทำมันได้ไกลขนาดนี้",
  ui_story_5037_50370701_332_dialog_content = "Carleen รอง ขอบคุณทั้งคู่ที่อยู่เคียงข้างฉันเสมอและสอนฉันมากมายในช่วงสองสามวันที่ผ่านมา",
  ui_story_5037_50370701_333_dialog_content = "อย่าพูดถึงมัน! มีเพียงสิ่งเล็กน้อยที่ไม่ถูกต้องในคำพูดของคุณ",
  ui_story_5037_50370701_334_dialog_content = "หา?",
  ui_story_5037_50370701_335_dialog_content = "เราไม่ได้เพิ่งช่วยคุณเมื่อสองสามวันที่ผ่านมาใช่ไหม?",
  ui_story_5037_50370701_336_dialog_content = "เธอพูดถูก เราอยู่ด้วยกันมาตลอดไม่ใช่เหรอ?",
  ui_story_5037_50370701_337_dialog_content = "นั่นสินะ จริงของเธอ",
  ui_story_5037_50370701_338_dialog_content = "ให้ฉันลองอีกครั้ง!",
  ui_story_5037_50370701_339_dialog_content = "โอ้ ผ่อนคลายหน่อยได้ไหม เราทุกคนเป็นเพื่อนกันที่นี่ ดังนั้นจึงไม่จำเป็นต้องเป็นทางการมาก!",
  ui_story_5037_50370701_340_dialog_content = "อย่างไรก็ตามคาดเดาอะไร",
  ui_story_5037_50370701_341_dialog_content = "ในการเดินทางไปอิลลูมินาครั้งล่าสุด ฉันสังเกตเห็นว่าทั้งภูมิภาคกลายเป็นไอดอลไปแล้ว!",
  ui_story_5037_50370701_342_dialog_content = "ฉันคิดว่าเจ้าหน้าที่วิเวียนกำลังวางแผนงานใหญ่เพื่อเลือกกลุ่มไอดอลเพื่อเป็นตัวแทนของสหพันธ์อิลลูมินาทั้งหมด!",
  ui_story_5037_50370701_343_dialog_content = "อะไร ไอดอลอิลลูมิน่า?!",
  ui_story_5037_50370701_344_dialog_content = "ปล่อยให้เราคำรามและทำให้การแสดงมีชีวิตชีวา!",
  ui_story_5037_50370701_345_dialog_content = "อืม? เกิดอะไรขึ้นกับฝูงชนที่เงียบชะมัด?",
  ui_story_5037_50370701_346_dialog_content = "พวกคุณตื่นตะลึงกับการแสดงอันน่าทึ่งของฉันจนลืมปรบมือหรือเปล่า?",
  ui_story_5037_50370701_347_dialog_content = "ฮ่าฮ่าฮ่าฮ่าฮ่า!",
  ui_story_5037_50370701_348_dialog_content = "*หายใจเข้า*",
  ui_story_5037_50370701_349_dialog_content = "อืม? มีอะไรบางอย่างผิดปกติ, PlayerName? คุณดูซีดเล็กน้อย",
  ui_story_5037_50370701_350_dialog_content = "ฉัน-ไม่เป็นอะไร!",
  ui_story_5037_50370701_351_dialog_content = "ฉันแน่ใจว่าการค้นหาไอดอลชั้นนำของ Illumina จะเป็นประสบการณ์ที่ยากจะลืมเลือน!",
  ui_story_5037_50370701_352_dialog_content = "การแข่งขันไอดอลเหล่านี้ควรค่าแก่การพิจารณาอย่างจริงจัง บางทีฉันควรจะแนะนำเหตุการณ์ที่คล้ายกันสำหรับ Lumopolis ให้พ่อของฉันฟัง?",
  ui_story_5037_50370701_353_dialog_content = "เอ่อ คิดว่าพวกขุนนางแห่งลูโมโพลิสจะยอมทำเรื่องแบบนี้เหรอ?",
  ui_story_5037_50370701_354_dialog_content = "ฉันสงสัยว่ามันจะไม่ง่าย",
  ui_story_5037_50370701_355_dialog_content = "แต่ไม่มีการปฏิเสธความรู้มากมายที่ฉันได้รับจากประสบการณ์นี้",
  ui_story_5037_50370701_356_dialog_content = "อันที่จริง ฉันเชื่อว่าในที่สุดฉันก็เห็นคุณค่าที่แท้จริงของการแสดงเสน่ห์ให้โลกได้เห็น",
  ui_story_5037_50370701_357_dialog_content = "น่าแปลกที่ฉันรู้สึกราวกับว่าจู่ๆ มีของหนักถูกยกขึ้นจากไหล่ของฉัน",
  ui_story_5037_50370701_358_dialog_content = "อ๋อ เข้าใจแล้ว",
  ui_story_5037_50370701_359_dialog_content = "ฉันคิดว่าคุณใกล้เข้ามาอีกก้าวหนึ่งในการเดินทางเพื่อสืบต่อจากพ่อของคุณ คาร์ลีน!",
  ui_story_5037_50370701_360_dialog_content = "คุณคิดว่าสิ่งนี้มีส่วนเกี่ยวข้องกับสิ่งนั้นหรือไม่?",
  ui_story_5037_50370701_361_dialog_content = "มันทำได้ถ้าคุณคิดเกี่ยวกับมันจริงๆ",
  ui_story_5037_50370701_362_dialog_content = "โอกาสยังไงเหรอ?",
  ui_story_5037_50370701_363_dialog_content = "อาหารเริ่มเย็นแล้ว! มาขุดกันเถอะ!",
  ui_story_5037_50370701_364_dialog_content = "คุณพูดถูก มาฉลองชัยชนะในขณะที่อาหารยังอุ่นๆ กันเถอะ",
  ui_story_5037_50370701_365_dialog_content = "ถึง PlayerName, ผู้ผลิตที่ดีที่สุด!",
  ui_story_5037_50370701_366_dialog_content = "ชนแก้ว!",
  ui_story_5037_50370701_367_option_content = "ชนแก้ว!",
  ui_story_5037_50370801_1_dialog_content = "ฝึกออกแบบท่าเต้น ฝึกร้อง ช่วงถามตอบ ติดต่อเจ้าของสถานที่จัดงานแฟนมีต...",
  ui_story_5037_50370801_2_dialog_content = "?",
  ui_story_5037_50370801_3_dialog_content = "ฉันควรจะติดต่อเจ้าของช่วงระหว่างมื้อกลางวันกับมื้อค่ำ แต่นักข่าวจะมาตอนบ่ายนี้...",
  ui_story_5037_50370801_4_dialog_content = "...",
  ui_story_5037_50370801_5_dialog_content = "ฉันยังต้องเผื่อเวลาให้โกลดีพักผ่อนเพียงพอ รวมถึงเปลี่ยนเสื้อผ้าและแต่งหน้าด้วย โดยทั้งหมดนี้เกิดขึ้นในวันเดียว...",
  ui_story_5037_50370801_6_dialog_content = "...?",
  ui_story_5037_50370801_7_dialog_content = "ฉันต้องทำงานทั้งวันอีกแล้ว!",
  ui_story_5037_50370801_8_dialog_content = "PlayerName?",
  ui_story_5037_50370801_9_dialog_content = "ว้าว!!!",
  ui_story_5037_50370801_10_dialog_content = "โอ้ แค่คุณเท่านั้น โกลดี้ ใจฉันแทบจะหลุดออกมานอกอกอยู่แล้ว",
  ui_story_5037_50370801_11_dialog_content = "ฉันขอถามสิ่งที่คุณพึมพำอยู่ตรงนี้ได้ไหม",
  ui_story_5037_50370801_12_dialog_content = "จริงๆ แล้ว ดูเหมือนว่าคุณค่อนข้างมีพลังงานน้อย อยากจะไปซ้อมเต้นกับผมให้สดชื่นขึ้นไหม?",
  ui_story_5037_50370801_13_dialog_content = "ออกกำลังกายเพียงเล็กน้อยก็สามารถช่วยให้สุขภาพดีได้!",
  ui_story_5037_50370801_14_dialog_content = "โปรดิวเซอร์ที่มีสุขภาพดีมีความสำคัญต่อความสำเร็จของไอดอล! คุณจะติดตามคอนเสิร์ตและกิจกรรมทั้งหมดของฉันได้อย่างไร",
  ui_story_5037_50370801_15_dialog_content = "ใช่ แต่ฉันยังคงวางแผนกำหนดการอยู่...",
  ui_story_5037_50370801_16_dialog_content = "มีอะไรให้ทำมากมายในแต่ละวัน เมื่อฉันทำสิ่งหนึ่งเสร็จ ฉันไปทำสิ่งต่อไปก็สายไปแล้ว...",
  ui_story_5037_50370801_17_dialog_content = "แม้แต่การพยายามพักผ่อนให้พอดีในเวลาไม่กี่นาทีก็แทบจะเป็นไปไม่ได้แล้ว!",
  ui_story_5037_50370801_18_dialog_content = "ฉันเดาว่าฉันไม่ใช่โปรดิวเซอร์ที่เก่งกาจขนาดนั้น...",
  ui_story_5037_50370801_19_dialog_content = "ไม่มีทาง! คุณเป็นผู้ผลิตที่ยอดเยี่ยม!",
  ui_story_5037_50370801_20_dialog_content = "คุณเพิ่งทำงานได้เพียงไม่กี่วัน แต่คุณก็คุ้นเคยกับข้อกำหนดรายวันของงานเป็นอย่างดี! นั่นไม่ใช่สิ่งที่ใคร ๆ ก็ทำได้ คุณก็รู้!",
  ui_story_5037_50370801_21_dialog_content = "ดังนั้นอย่ากดดันตัวเองมากเกินไป โอเค? นี่ อยากเลี้ยง Marshmallow ไหม?",
  ui_story_5037_50370801_22_dialog_content = "ฉันรู้สึกดีขึ้นเสมอหลังจากได้ลูบขนนุ่มฟูของมัน!",
  ui_story_5037_50370801_23_dialog_content = "โฮ่ง!",
  ui_story_5037_50370801_24_dialog_content = "แน่นอน ทำไมไม่—",
  ui_story_5037_50370801_25_dialog_content = "รอเดี๋ยวสิ",
  ui_story_5037_50370801_26_dialog_content = "มีอะไรเหรอ",
  ui_story_5037_50370801_27_dialog_content = "ฉันลืมโทรหาหนังสือพิมพ์เกี่ยวกับการสัมภาษณ์ในวันพรุ่งนี้! ฉันยังไม่ได้กำหนดเวลาสำหรับมัน!",
  ui_story_5037_50370801_28_dialog_content = "ขอโทษนะโกลดี้! ฉันต้องไปแล้ว!",
  ui_story_5037_50370801_29_dialog_content = "...",
  ui_story_5037_50370801_30_dialog_content = "<color=#828282>สักครู่ต่อมา</color>",
  ui_story_5037_50370801_31_dialog_content = "ว้า... ขอบคุณพระเจ้าที่ฉันมาทันเวลา",
  ui_story_5037_50370801_32_dialog_content = "พวกเขาเป็นหนึ่งในหนังสือพิมพ์ที่ใหญ่ที่สุด ถ้าฉันปล่อยให้พวกเขาแขวนคอ มันจะทำลายชื่อเสียงของโกลดี้",
  ui_story_5037_50370801_33_dialog_content = "ยินดีต้อนรับกลับ, PlayerName!",
  ui_story_5037_50370801_34_dialog_content = "โอ้ สวัสดี โกลดี้! ขอโทษนะ ฉันรีบมากจนลืมบอกลา...",
  ui_story_5037_50370801_35_dialog_content = "ไม่เป็นไร. ฉันรู้ว่าเป็นเพราะช่วงนี้คุณยุ่งกับงานมาก",
  ui_story_5037_50370801_36_dialog_content = "การเป็นโปรดิวเซอร์นั้นค่อนข้างยาก แม้ว่าฉันจะปรับตัวเข้ากับงานได้ช้าในช่วงสองสามวันที่ผ่านมา",
  ui_story_5037_50370801_37_dialog_content = "งานยังเรียกร้องอยู่จริงๆ!",
  ui_story_5037_50370801_38_dialog_content = "ถ้าทั้งหมดที่ฉันต้องทำคือการวางแผนตารางเวลา มันคงไม่ใช่เรื่องยากเลย",
  ui_story_5037_50370801_39_dialog_content = "แต่นอกเหนือจากการวางแผนทั้งหมดแล้ว ฉันต้องต่อสู้กับพวกปาปารัซซี่ทุกครั้ง และคิดสิ่งที่ถูกต้องที่จะพูดทุกครั้ง...",
  ui_story_5037_50370801_40_dialog_content = "มันเหนื่อย...",
  ui_story_5037_50370801_41_dialog_content = "ฉันรู้ว่ามันเป็นงานที่หนัก",
  ui_story_5037_50370801_42_dialog_content = "แต่ไม่ว่าคุณจะเหนื่อยแค่ไหน คุณก็หาทางทำงานให้สำเร็จได้เสมอ PlayerName!",
  ui_story_5037_50370801_43_dialog_content = "นั่นคือสิ่งที่ฉันคิดว่าเหลือเชื่อมากเกี่ยวกับคุณ!",
  ui_story_5037_50370801_44_dialog_content = "ขอบคุณโกลดี้! แค่ได้ยินเธอพูดก็ทำให้ฉันรู้สึกเหนื่อยน้อยลงมาก!",
  ui_story_5037_50370801_45_dialog_content = "ดู? ทุกคนต้องการกำลังใจเป็นครั้งคราว ไม่ว่าพวกเขาจะเป็นใครก็ตาม!",
  ui_story_5037_50370801_46_dialog_content = "ตอนนี้คุณพูดถึงมัน ... คุณจัดการทั้งหมดนี้ด้วยตัวเองมาก่อนหรือไม่ โกลดี้?",
  ui_story_5037_50370801_47_dialog_content = "ไม่ใช่แค่การเป็นไอดอล แต่ยังเป็นโปรดิวเซอร์ของตัวเองอีกด้วย...",
