  ui_story_5037_50370801_53_dialog_content = "แม้แต่กับคนอย่างฉัน การจัดการงานสองงานที่แตกต่างกันโดยสิ้นเชิงนั้นไม่ใช่เรื่องง่าย",
  ui_story_5037_50370801_54_dialog_content = "ที่ผ่านมาฉันเจออุปสรรคมาทุกรูปแบบ มีหลายครั้งที่ฉันอยากจะยอมแพ้และล้มเลิก",
  ui_story_5037_50370801_55_dialog_content = "คุณเคยรู้สึกอยากเลิกก่อนไหม? ฉันไม่สามารถจินตนาการได้",
  ui_story_5037_50370801_56_dialog_content = "มันเป็นหนึ่งในความลับที่ใหญ่ที่สุดของฉัน ดังนั้นอย่าไปบอกคนอื่นไปทั่ว!",
  ui_story_5037_50370801_57_dialog_content = "ไม่คิดไม่ฝัน! ในฐานะโปรดิวเซอร์ของคุณ ฉันจะไม่พูดหรือทำอะไรเพื่อทำร้ายคุณหรือชื่อเสียงของคุณ!",
  ui_story_5037_50370801_58_dialog_content = "ฮิฮิ! ดีใจที่ได้ยิน!",
  ui_story_5037_50370801_59_dialog_content = "แต่เพื่อตอบคำถามของคุณ... ใช่ ฉันต้องจัดการงานทั้งหมดด้วยตัวเองตอนที่ฉันมาเป็นไอดอลครั้งแรก",
  ui_story_5037_50370801_60_dialog_content = "ฝึกฝน วางแผน และหลีกเลี่ยงปาปารัซซี่... ทั้งหมดทั้งมวล",
  ui_story_5037_50370801_61_dialog_content = "เมื่อก่อนฉันได้นอนแค่วันละหนึ่งหรือสองชั่วโมงเท่านั้น!",
  ui_story_5037_50370801_62_dialog_content = "ฉันต้องตื่นแต่เช้าทุกวันเพื่อชดเชยการฝึกซ้อมที่ฉันพลาดไปเมื่อวันก่อน",
  ui_story_5037_50370801_63_dialog_content = "บ้าไปแล้ว!",
  ui_story_5037_50370801_64_dialog_content = "ฉันเคยนอนดึกแต่นอนแค่หนึ่งถึงสองชั่วโมง? วันรุ่งขึ้นฉันแทบจะลุกจากเตียงไม่ได้เลย น้อยกว่าทุกวัน...",
