  ui_story_5037_50370801_68_dialog_content = "แต่สุดท้ายแล้วคุณก็สามารถฝ่าฟันผ่านช่วงเวลาที่ยากลำบากและกลายมาเป็นไอดอลชื่อดังอย่างที่เป็นคุณในทุกวันนี้!",
  ui_story_5037_50370801_69_dialog_content = "ใช่แล้ว!",
  ui_story_5037_50370801_70_dialog_content = "เมื่อไหร่ก็ตามที่ฉันรู้สึกยอมแพ้ ฉันจะโยนกระสุนนำโชคขึ้นไปในอากาศ ถ้ามันชี้ลง แสดงว่ามีเรื่องดีๆ กำลังจะเกิดขึ้น!",
  ui_story_5037_50370801_71_dialog_content = "ในตอนนั้น กระสุนนำโชคของฉันมักจะชี้ลง ฉันเลยรู้ว่าถ้าฉันทำต่อไป... ฉันจะกลายเป็นไอดอลที่ฉันใฝ่ฝันมาตลอด!",
