  ui_story_5037_50370901_10_dialog_content = "อ้อ แค่ซื้อวัตถุดิบแค่นั้นเอง ฉันได้ยินมาว่าตอนนี้คุณเป็นโปรดิวเซอร์รายใหญ่ใน Umbraton ฉันเลยคิดว่าจะแวะไปดูสักหน่อย!",
