  ui_story_5037_50370901_14_dialog_content = "ฮะ? วันนี้คุณไม่อยากท้าทายฉันเหรอ ต้องบอกว่าไม่เหมือนคุณเลย...",
  ui_story_5037_50370901_15_dialog_content = "เพราะฉันยังมีงานอีกมากที่ต้องทำในช่วงบ่ายนี้ มันง่ายสำหรับฉันที่จะลืมเวลาเมื่อฉันเล่นวิดีโอเกม...",
