  ui_story_5037_50370901_25_dialog_content = "เวลาของเรากำลังจะหมดลง แต่งานก็กองพะเนินเทินทึก บางครั้งไม่มีทางเลือกอื่นนอกจากยอมสละเวลาว่างเล็กน้อย...",
  ui_story_5037_50370901_26_dialog_content = "... คุณใช้ช่วงพักเพื่อทำงานคอนเสิร์ตในช่วง 2-3 วันที่ผ่านมาหรือเปล่า?",
