  ui_story_5037_50370901_29_dialog_content = "หากไม่ได้พักผ่อนอย่างเหมาะสม คุณภาพงานของคุณก็จะแย่ลง! คุณจะไม่สามารถทำอะไรได้เลยในอัตรานี้!",
