  ui_story_5037_50370901_31_dialog_content = "ไปเดินเล่น รับอากาศบริสุทธิ์ แล้วอย่ากลับ จนกว่าคุณจะสบายดีและได้พักผ่อน!",
  ui_story_5037_50370901_32_dialog_content = "ท-นั่นไม่จำเป็นเลยจริงๆ...",
  ui_story_5037_50370901_33_dialog_content = "ฉันจะไม่ยอมรับคำตอบ! สิ่งนี้เกี่ยวข้องกับทั้งสุขภาพและประสิทธิภาพในการทำงานของคุณ",
  ui_story_5037_50370901_34_dialog_content = "B-แต่ถ้าฉันเป็นโปรดิวเซอร์ของคุณ คุณจะทำอย่างไรถ้าฉันไม่อยู่",
  ui_story_5037_50370901_35_dialog_content = "คุณไม่จำเป็นต้องกังวลเกี่ยวกับเรื่องนั้น ฉันบอกคุณแล้วฉันเป็นโปรดิวเซอร์ของตัวเองเป็นเวลานานที่สุด นี่ไม่ใช่เรื่องใหญ่",
  ui_story_5037_50370901_36_dialog_content = "พักผ่อนได้แล้ว อย่ากลับมาที่ออฟฟิศจนกว่าจะถึงพรุ่งนี้เช้า!",
  ui_story_5037_50370901_37_dialog_content = "<color=#828282>แคว่ก!</color>",
  ui_story_5037_50370901_38_dialog_content = "(เธอเพิ่งผลักฉันออกจากประตู ... )",
  ui_story_5037_50370901_39_dialog_content = "(อืม... งั้นฉันไปเดินเล่นก่อนนะ)",
  ui_story_5037_50370901_40_dialog_content = "<color=#828282>ไม่กี่นาทีต่อมาที่ร้านกาแฟ</color>",
  ui_story_5037_50370901_41_dialog_content = "ฉันจะได้อะไรจากคุณ",
  ui_story_5037_50370901_42_dialog_content = "มาดูเมนูกันเลย...",
  ui_story_5037_50370901_43_dialog_content = "“เค้กสามสี”?",
  ui_story_5037_50370901_44_dialog_content = "ภารกิจของเราคือการจัดคอนเสิร์ตสามครั้งภายในระยะเวลาหนึ่ง",
  ui_story_5037_50370901_45_dialog_content = "เรายังเหลืออีกสองคอนเสิร์ต...",
  ui_story_5037_50370901_46_dialog_content = "ทำไมจู่ๆ ฉันถึงคิดเรื่องนั้นขึ้นมา! กลับไปที่เมนู!",
  ui_story_5037_50370901_47_dialog_content = "มาดูกัน... แฝดเค้ก?",
  ui_story_5037_50370901_48_dialog_content = "หลังจากการแสดงเริ่มขึ้น ผู้ชมสามารถทำตามความต้องการและเคลื่อนไหวไปมาระหว่างเวทีได้อย่างอิสระ",
  ui_story_5037_50370901_49_dialog_content = "ในท้ายที่สุด สเตจใดที่สามารถดึงดูดฝูงชนได้มากขึ้นจะได้รับการประกาศให้เป็นผู้ชนะ",
  ui_story_5037_50370901_50_dialog_content = "เฮ้อ... ฉันสงสัยว่าเราจะทำอย่างไรให้ผู้คนสนใจ?",
  ui_story_5037_50370901_51_dialog_content = "Kyllo มีพลังในการสร้างแรงบันดาลใจจริง ๆ หรือไม่?",
  ui_story_5037_50370901_52_dialog_content = "ฉันควรหา Kyllo ของฉันเองเพื่อกัดข้อเท้าของฉันหรือไม่?",
  ui_story_5037_50370901_53_dialog_content = "ทำไมฉันหยุดกังวลไม่ได้!",
  ui_story_5037_50370901_54_dialog_content = "ขออภัย ฉันคิดว่ายังต้องการเวลามากกว่านี้เพื่อดูเมนู",
  ui_story_5037_50370901_55_dialog_content = "ไม่ใช่ปัญหา. เพียงโทรหาฉันเมื่อคุณพร้อม",
  ui_story_5037_50370901_56_dialog_content = "แม้ว่าฉันจะไม่ได้ทำงาน แต่ฉันก็ไม่สามารถหยุดคิดถึงคอนเสิร์ตการประเมินได้ อีกไม่กี่วันแล้ว...",
  ui_story_5037_50370901_57_dialog_content = "ฉันยังไม่ได้วางแผนกำหนดการของ Goldie สำหรับวันพรุ่งนี้เช่นกัน อดไม่ได้ที่จะรู้สึกไม่สบายใจทุกครั้งที่คิดถึงเรื่องนี้...",
  ui_story_5037_50370901_58_dialog_content = "เฮ้อ... กาแฟกับเค้กรสชาติไม่ค่อยดีเท่าไหร่เวลาเครียดๆ",
  ui_story_5037_50370901_59_dialog_content = "ฉันสงสัยว่าการฝึกของโกลดี้เป็นอย่างไรบ้าง...?",
  ui_story_5037_50370901_60_dialog_content = "ไม่เป็นไรถ้าฉันจะแอบดูเพื่อให้แน่ใจว่าเธอไม่เป็นไร ใช่ไหม",
  ui_story_5037_50370901_61_dialog_content = "<color=#828282>ภายนอกหน่วยงาน</color>",
  ui_story_5037_50370901_62_dialog_content = "นี่น่าจะเป็นห้องซ้อม ฉันควรจะสามารถมองเข้าไปข้างในผ่านหน้าต่างได้",
  ui_story_5037_50370901_63_dialog_content = "ฉันเห็นโกลดี้... แต่คนข้างๆเธอ...",
  ui_story_5037_50370901_64_dialog_content = "สวัสดี โกลดี้? ฉันอยู่กับ Daily Drivel แหล่งข่าวซุบซิบที่ดังที่สุดใน Umbraton!",
  ui_story_5037_50370901_65_dialog_content = "ฉันสังเกตเห็นว่าคุณกระแทกประตูใส่โปรดิวเซอร์ของคุณเมื่อวันก่อน",
  ui_story_5037_50370901_66_dialog_content = "คำพูดบนท้องถนนคือคุณไม่เคยมีข้อตกลงที่ดีกับเขา และคุณไล่เขาออกทันที! เป็นเรื่องจริงหรือไม่?",
  ui_story_5037_50370901_67_dialog_content = "PlayerName และฉันอยู่ในเงื่อนไขที่ดีที่สุด ขอบคุณมาก เราเป็นเพื่อนที่ดีมาโดยตลอด",
  ui_story_5037_50370901_68_dialog_content = "แล้วคุณจะอธิบายฉากก่อนหน้านี้ได้อย่างไร?",
  ui_story_5037_50370901_69_dialog_content = "โยนโปรดิวเซอร์ของคุณทิ้งแล้วปล่อยให้เขายืนเฉยๆ ข้างถนน... ฉันไม่เคยเห็นภาพที่น่าสงสารแบบนี้มาก่อน!",
  ui_story_5037_50370901_70_dialog_content = "นั่นเป็นเพราะ—",
