  ui_story_5037_50370901_72_dialog_content = "โกลดีไม่เคยพบหรือจัดการกับเขามาก่อน... ถ้าเขาไม่หยุด เขาจะก่อเรื่องขึ้นอีก!",
  ui_story_5037_50370901_73_dialog_content = "ฉันต้องช่วยเธอให้ได้!",
  ui_story_5037_50370901_74_dialog_content = "โปรดิวเซอร์ตัวน้อยช่างน่าเศร้า...",
  ui_story_5037_50370901_75_dialog_content = "เฮ้! เกิดอะไรขึ้นที่นี่?",
