  ui_story_5037_50370901_99_dialog_content = "ใช่... นั่นเป็นเหตุผลที่ฉันแค่อยากจะจบเรื่องด้วย คุณรู้ไหม? ฉันไม่คิดว่าฉันจะสามารถพักผ่อนได้เต็มที่จนกว่าคอนเสิร์ตจะจบลง",
