  ui_story_5037_50370901_104_dialog_content = "ตอนนี้ฉันบอกได้เลยว่าฉันค่อนข้างจะหัวเสียเล็กน้อยเมื่อต้องบอกเลิกคนพวกนั้น",
  ui_story_5037_50370901_105_dialog_content = "ฉันทำให้คุณเสียเปรียบหรือเปล่า",
