  ui_story_5037_50370901_107_dialog_content = "ตั้งแต่คุณมาเป็นโปรดิวเซอร์ของฉัน ฉันสามารถอุทิศตัวเองให้กับการฝึกฝน พัฒนาทักษะทั้งหมดของฉันโดยกลุ่มทั้งหมด",
  ui_story_5037_50370901_108_dialog_content = "ฉันไม่ใช่โกลดี้คนเดิมที่ฉันเคยเป็น ฉันคือ Super Goldie ที่ได้รับการปรับปรุงใหม่!",
  ui_story_5037_50370901_109_dialog_content = "ฮ่า ๆ ๆ ๆ! ฉันโล่งใจที่คุณไม่คิดว่าฉันรั้งคุณไว้",
