  ui_story_5037_50370901_112_dialog_content = "คุณไม่ต้องกังวลเกี่ยวกับฉันอีกต่อไป โกลดี้ ฉันรู้ว่าตอนนี้เรายุ่งมาก แต่ฉันสัญญาว่าต่อจากนี้ไปฉันจะพักผ่อนให้เพียงพอและออกกำลังกาย!",
  ui_story_5037_50370901_113_dialog_content = "จากนั้นฉันก็จะปฏิบัติตามการตัดสินใจของคุณทั้งหมดเช่นกัน",
  ui_story_5037_50370901_114_dialog_content = "ฉันเชื่อในตัวคุณ!",
  ui_story_5037_50371001_1_dialog_content = "คอนเสิร์ตประเมินจบลงแล้ว!",
  ui_story_5037_50371001_2_dialog_content = "ในที่สุดเราก็ผ่านความท้าทายที่ยิ่งใหญ่ที่สุดของเรา! ขอบคุณพระเจ้า.",
