  ui_story_5037_50371001_23_dialog_content = "มันเป็นเพลงสำหรับคอนเสิร์ตจบการศึกษา ท้ายที่สุดแล้ว... ดังนั้นฉันจึงเขียนมันด้วยความขอบคุณทั้งหมดที่อยู่ในใจ!",
  ui_story_5037_50371001_24_dialog_content = "แต่รู้สึกเหมือนมีอะไรมากกว่าแค่ความขอบคุณ",
  ui_story_5037_50371001_25_dialog_content = "มันฟังดูเศร้าและโหยหา... ไม่รู้สิ",
  ui_story_5037_50371001_26_dialog_content = "เพราะเป็นเพลงอำลา",
  ui_story_5037_50371001_27_dialog_content = "แต่คุณกำลังบอกลาใคร โกลดี้?",
  ui_story_5037_50371001_28_dialog_content = "มีบางอย่างที่ฉันยังไม่เข้าใจ... คอนเสิร์ตรับปริญญาคืออะไรกันแน่?",
  ui_story_5037_50371001_29_dialog_content = "คอนเสิร์ตจบการศึกษาจัดขึ้นสำหรับไอดอลที่ลาออกและลาออก",
  ui_story_5037_50371001_30_dialog_content = "เป็นโอกาสที่ไอดอลจะได้อำลาแฟนๆ",
  ui_story_5037_50371001_31_dialog_content = "อะไร—?!",
  ui_story_5037_50371001_32_dialog_content = "คุณจะไม่เป็นไอดอลอีกต่อไปหลังจากคอนเสิร์ตนี้???",
  ui_story_5037_50371001_33_dialog_content = "คุณกำลังพูดถึงอะไร ฉันยังมีเวลาอีกหลายปีในการเป็นไอดอลในตัวฉัน",
  ui_story_5037_50371001_34_dialog_content = "คอนเสิร์ตนี้เป็นเพียงวิดีโอโปรโมตเท่านั้น! คอนเสิร์ตรับปริญญาจริง ๆ ของฉันคงมีไม่นานหรอก!",
  ui_story_5037_50371001_35_dialog_content = "นอกจากนี้... ในฐานะโปรดิวเซอร์ของฉัน ฉันอยากให้คุณสัมผัสประสบการณ์การทำงานกับไอดอลไปจนสิ้นสุดอาชีพของเธอ!",
  ui_story_5037_50371001_36_dialog_content = "ฉันยังคงวางแผนที่จะเป็นไอดอลต่อไป โง่!",
  ui_story_5037_50371001_37_dialog_content = "คุณทำให้ฉันกลัว...",
  ui_story_5037_50371001_38_dialog_content = "วินาทีนั้น ฉันคิดว่าคุณจบจากการเป็นไอดอลแล้ว",
  ui_story_5037_50371001_39_dialog_content = "ไม่ได้เด็ดขาด!",
  ui_story_5037_50371001_40_dialog_content = "สำหรับผม คอนเสิร์ตครั้งหน้านี้เป็นเพียงบทสรุปบทหนึ่งในอาชีพของผม",
  ui_story_5037_50371001_41_dialog_content = "มันจะทำหน้าที่เป็นการปิดฉากตลอดเวลาที่เราใช้ร่วมกัน ความยากลำบากและชัยชนะทั้งหมดที่เราแบ่งปัน!",
  ui_story_5037_50371001_42_dialog_content = "เข้าใจแล้ว",
  ui_story_5037_50371001_43_dialog_content = "พูดตามตรง ฉันนึกภาพคุณไม่ออกเลยว่าคุณจะทำอะไรอย่างอื่นในชีวิต...",
  ui_story_5037_50371001_44_dialog_content = "ในความคิดของฉัน คุณคือต้นแบบของไอดอล",
  ui_story_5037_50371001_45_dialog_content = "ฉันไม่สามารถบอกคุณได้ว่ามันมีความหมายกับฉันมากแค่ไหน!",
  ui_story_5037_50371001_46_dialog_content = "ถ้านั่นคือความประทับใจที่ฉันมอบให้ แสดงว่าฉันทำงานถูกต้องแล้ว!",
  ui_story_5037_50371001_47_dialog_content = "แต่สุดท้ายแล้ว...ฉันก็เป็นแค่คนธรรมดาเหมือนคนอื่นๆ",
  ui_story_5037_50371001_48_dialog_content = "สักวันฉันจะต้องจัดคอนเสิร์ตรับปริญญาจริงๆ และบอกลาแฟนๆ",
  ui_story_5037_50371001_49_dialog_content = "เรามาพูดถึงสิ่งที่น่าหดหู่ใจกันดีกว่า...",
  ui_story_5037_50371001_50_dialog_content = "ใช่ไหม? ฉันไม่คิดอย่างนั้นจริงๆ",
  ui_story_5037_50371001_51_dialog_content = "ไม่นะ",
  ui_story_5037_50371001_52_dialog_content = "การสำเร็จการศึกษาเป็นเพียงส่วนหนึ่งของชีวิตไอดอล และย่อมมาถึงพวกเราทุกคนอย่างหลีกเลี่ยงไม่ได้ไม่ว่าเราจะยินดีหรือไม่ก็ตาม",
  ui_story_5037_50371001_53_dialog_content = "แทนที่จะพยายามหลีกเลี่ยง ฉันต้องการทำทุกอย่างที่ทำได้เพื่อให้แน่ใจว่าคอนเสิร์ตจบการศึกษาของฉันคือคอนเสิร์ตที่ดีที่สุดเท่าที่เคยมีมา!",
  ui_story_5037_50371001_54_dialog_content = "ไม่ว่าจะเกิดอะไรขึ้น ฉันก็ไม่อยากเสียใจสำหรับตัวฉันหรือแฟนๆ",
  ui_story_5037_50371001_55_dialog_content = "ไม่ว่าจะเกิดอะไรขึ้น ฉันต้องการให้แน่ใจว่าฉันส่องสว่างในใจพวกเขาไปตลอดชีวิต",
  ui_story_5037_50371001_56_dialog_content = "นั่นเป็นเหตุผลที่ฉันจะทำให้ดีที่สุดต่อไปจนกว่าจะถึงวันรับปริญญา!",
  ui_story_5037_50371001_57_dialog_content = "นั่นฟังดูคล้ายกับคุณมาก!",
  ui_story_5037_50371001_58_dialog_content = "เอาล่ะ ถึงเวลาเลิกเป็นไอดอลแล้ว...คุณจะทำอย่างไร?",
  ui_story_5037_50371001_59_dialog_content = "อืม... ฉันยังไม่ได้ตัดสินใจจริงๆ!",
  ui_story_5037_50371001_60_dialog_content = "ฉันมีไอเดียมากมาย แต่ตอนนี้... สิ่งที่ฉันชอบที่สุดคือเปิดร้านคาเฟ่สัตว์เลี้ยงของตัวเอง!",
