  ui_story_5037_50371001_62_dialog_content = "ฟังดูเป็นความคิดที่ดี!",
  ui_story_5037_50371001_63_dialog_content = "ดื่มกาแฟและเล่นกับสัตว์น้อยน่ารัก...เหมือนอยู่ในความฝัน",
  ui_story_5037_50371001_64_dialog_content = "ฉันอยู่ที่นั่นกับคุณ!",
  ui_story_5037_50371001_65_dialog_content = "เมื่อไหร่ก็ตามที่ฉันรู้สึกเหนื่อย การลูบขนนุ่มฟูของ Marshmallow ช่วยให้ฉันผ่อนคลายได้เสมอ",
  ui_story_5037_50371001_66_dialog_content = "ในฐานะไอดอล งานของฉันคือการให้กำลังใจทุกคนด้วยพลังของเพลงและการเต้น",
