  ui_story_5037_50371001_68_dialog_content = "ไม่ว่าจะเกิดอะไรขึ้นในชีวิต ฉันรู้ว่าฉันจะโอเคกับมัน",
  ui_story_5037_50371101_1_dialog_content = "(ฉันพบจดหมายจากวิคในสำนักงานวันนี้ จ่าหน้าซองถึงฉัน)",
  ui_story_5037_50371101_2_dialog_content = "(มันบอกว่าให้ไปรอเขาที่ห้องเต้นรำในวันพรุ่งนี้... เขาอยากจะถามฉันเรื่องส่วนตัวบ้าง)",
