  ui_story_5037_50371101_10_dialog_content = "เอาล่ะ ให้ฉันพูดตรงๆ เกี่ยวอะไรกับปาปารัซซี่ที่วนเวียนอยู่แถวนี้ทุกวัน?",
  ui_story_5037_50371101_11_dialog_content = "ปาปารัซซี่?",
  ui_story_5037_50371101_12_dialog_content = "โอ้ คุณหมายถึงผู้ชายรูปร่างท้วมๆ มีหนวดเครานั่นน่ะเหรอ?",
  ui_story_5037_50371101_13_dialog_content = "ใช่นั่นคือคนเดียว! ดังนั้นคุณจึงรู้จักเขา!",
