  ui_story_5037_50371101_15_dialog_content = "ที่แย่กว่านั้นคือ ทุกครั้งที่ฉันไล่เขาออก... วันต่อมา เขาเขียนบทความแย่ๆ ใส่ร้ายอาจารย์และยกย่องโกลดี้แทน!",
  ui_story_5037_50371101_16_dialog_content = "บอกความจริง! เขาทำงานให้พวกคุณหรือเปล่า?",
