  ui_story_5037_50371101_18_dialog_content = "เราโดนเขาลวนลามทุกวันเช่นกัน!",
  ui_story_5037_50371101_19_dialog_content = "จริงเหรอ",
  ui_story_5037_50371101_20_dialog_content = "ดู? ฉันบอกคุณแล้วว่าไม่ใช่พวกเขา!",
