  ui_story_5037_50371101_22_dialog_content = "จ-จริงเหรอ",
  ui_story_5037_50371101_23_dialog_content = "ฉันเดาว่าฉันเพิ่งอ่านเนื้อหาเกี่ยวกับอาจารย์ผู้ไร้ประโยชน์ของฉัน...",
  ui_story_5037_50371101_24_dialog_content = "ถึงตอนนี้คุณพูดถึงมันแล้ว... ฉันคิดว่าฉันจำได้ว่าเคยดูบทความใส่ร้ายเกี่ยวกับ Vic เหมือนกัน",
