  ui_story_5037_50371101_27_dialog_content = "แม้ว่าฉันจะแน่ใจว่าได้ล็อกประตูทุกวันก่อนออกไปแล้ว เขาก็มักจะหาทางเข้าไปข้างในได้เสมอ...",
