  ui_story_5037_50371101_33_dialog_content = "ไม่! อาจารย์ยังมีการฝึกอีกมากที่ต้องทำ แล้วพบกันใหม่!",
  ui_story_5037_50371101_34_dialog_content = "เรามาทำให้ดีที่สุด โอเค?",
  ui_story_5037_50371101_35_dialog_content = "ได้เลย—",
  ui_story_5037_50371101_36_dialog_content = "<size=45>เดี๋ยวก่อน!</size>",
  ui_story_5037_50371101_37_dialog_content = "ฮะ? อะไรตอนนี้?",
