  ui_story_5037_50371101_39_dialog_content = "ย-ใช่...?",
  ui_story_5037_50371101_40_dialog_content = "คุณช่วยสอนวิธีจัดการกับปาปารัซซี่ให้ฉันทีได้ไหม? ฉันขอร้องคุณ!",
