  ui_story_5037_50371101_42_dialog_content = "เลิกใช้ผ้าคาดผมเช็ดน้ำตา!!",
  ui_story_5037_50371101_43_dialog_content = "*ดม* โอเค...",
  ui_story_5037_50371101_44_dialog_content = "ขอบคุณนักข่าวงี่เง่าคนนั้น และเรื่องโกหกทั้งหมดของเขา... ฉันเสียแฟนๆ ไปมากเกินกว่าจะเสียได้!",
  ui_story_5037_50371101_45_dialog_content = "วิธีเดียวที่จะชดเชยแฟนที่หายไปของฉันคือการฝึกฝนให้หนักขึ้นกว่าเดิมและเข้าร่วมกิจกรรมไอดอลให้ได้มากที่สุด",
  ui_story_5037_50371101_46_dialog_content = "เฟียก็ไม่ยอมปล่อยฉันเช่นกัน... เธอจ้องฉันเหมือนเหยี่ยวในระหว่างการฝึกซ้อม ดังนั้นฉันจึงไม่สามารถหย่อนใจได้เลยแม้แต่วินาทีเดียว!",
  ui_story_5037_50371101_47_dialog_content = "ทำไม แค่การฝึกซ้อมครั้งสุดท้าย ฉันพยายามกลั้นหายใจอยู่ครู่หนึ่ง... และเธอก็ทำให้ Kyllo กัดขาฉัน!",
  ui_story_5037_50371101_48_dialog_content = "เพียงแค่ดูที่นี้ PlayerName! ขาฉันมีรอยกัดยิ่งกว่าของเล่นเคี้ยว! คุณต้องช่วยฉัน...",
