  ui_story_5037_50371101_50_dialog_content = "ฉันรู้ว่าฉันไว้ใจคุณได้!",
  ui_story_5037_50371101_51_dialog_content = "ทีนี้เราควรเริ่มที่ไหนดี...",
  ui_story_5037_50371101_52_dialog_content = "ทำไมเราไม่ลองดู Daily Drivel ฉบับวันนี้ก่อนล่ะ? มาดูกัน...",
  ui_story_5037_50371101_53_dialog_content = "\"วิคเคยบรรยายตัวเองว่าอายุ 18 ปีชั่วนิรันดร์ แต่อายุจริงของเขานั้นมากกว่านั้นมาก\"?!",
  ui_story_5037_50371101_54_dialog_content = "ฉันหมายความว่านี่ฟังดูเหมือนคำพูดจริง",
  ui_story_5037_50371101_55_dialog_content = "อ๋อ จำได้! ฉันคิดว่าฉันพูดแบบนั้นเกี่ยวกับตัวเอง ใช่...",
