  ui_story_5037_50371101_57_dialog_content = "อายุจริงของฉันเป็นความลับ!",
  ui_story_5037_50371101_58_dialog_content = "ก็ได้... ฉันว่าไม่เป็นไร แค่อย่าลืมเก็บเป็นความลับ",
  ui_story_5037_50371101_59_dialog_content = "มันพูดอะไรอีก? \"วิคเชื่อว่าเขาอ่อนเยาว์และกระฉับกระเฉงกว่าโกลดี้ที่เคยโด่งดังมาก\"?!",
  ui_story_5037_50371101_60_dialog_content = "ฮะ? นั่นคือคำพูดของเขา ไม่ใช่ของฉัน! เขาพูดพร้อมกับชมการแสดงของฉัน!",
  ui_story_5037_50371101_61_dialog_content = "แล้ว...คุณตอบว่าอย่างไร?",
  ui_story_5037_50371101_62_dialog_content = "คำชมก็คือคำชม! ทำไมฉันจะปฏิเสธมัน?",
  ui_story_5037_50371101_63_dialog_content = "หากคุณเห็นด้วยกับสิ่งที่เขาพูด นั่นยิ่งทำให้คุณตกเป็นเป้าหมายได้ง่ายขึ้น Vic!",
  ui_story_5037_50371101_64_dialog_content = "ท-แล้วจะให้ตอบยังไงดีล่ะ?!",
  ui_story_5037_50371101_65_dialog_content = "คำพูดของเขามีไว้เพื่อหลอกให้คุณยอมรับว่าคุณคิดว่าคุณดีกว่าไอดอลคนอื่นๆ",
  ui_story_5037_50371101_66_dialog_content = "ดังนั้นหากคุณพบว่าตัวเองอยู่ในสถานการณ์คล้ายๆ กัน ลองถ่อมตัวมากขึ้นและบอกว่าคนอื่นดีกว่าคุณ ด้วยวิธีนี้เขาจะไม่มีอะไรต้องทำงานด้วย!",
  ui_story_5037_50371101_67_dialog_content = "ตกลงตกลง. ฉันจะลองครั้งต่อไป!",
  ui_story_5037_50371101_68_dialog_content = "มาอ่านกันต่อ...",
  ui_story_5037_50371101_69_dialog_content = "\"โปรดิวเซอร์ของ Vic ขึ้นชื่อเรื่องการคุกคามนักข่าวผู้บริสุทธิ์ด้วยสัตว์ป่าดุร้าย\"?!",
  ui_story_5037_50371101_70_dialog_content = "เฟีย... คุณทำอะไรลงไป?",
  ui_story_5037_50371101_71_dialog_content = "D-อย่ามองมาที่ฉัน!",
  ui_story_5037_50371101_72_dialog_content = "มันน่ารำคาญเกินไป ฉันเลยให้ Kyllo โยนมันออกไปที่ถนน!",
  ui_story_5037_50371101_73_dialog_content = "ฉันเข้าใจแล้ว... อย่าทำอย่างนั้นอีกต่อไป โอเค?",
  ui_story_5037_50371101_74_dialog_content = "ไม่ว่านักข่าวเหล่านี้จะระคายเคืองแค่ไหน การใช้ความรุนแรงก็ไม่ใช่วิธีที่ถูกต้องในการจัดการกับพวกเขา",
  ui_story_5037_50371101_75_dialog_content = "คุณเพียงแต่ให้เหตุผลมากขึ้นแก่พวกเขาในการกำหนดเป้าหมายคุณด้วยการใส่ร้าย",
  ui_story_5037_50371101_76_dialog_content = "แล้วฉันจะจัดการกับพวกมันยังไงดี?!",
  ui_story_5037_50371101_77_dialog_content = "ฉันไม่สามารถห้ามพวกมันเข้ามาได้ และฉันก็ปล่อยให้พวกมันออกไปไม่ได้... พวกมันเหมือนฝูงยุงแต่ดุร้ายยิ่งกว่า!",
  ui_story_5037_50371101_78_dialog_content = "เมื่อพวกเขากวนคุณแบบนั้น คุณทำได้เพียงยืนยันอย่างสุภาพว่าคุณไม่ยอมรับการสัมภาษณ์และเมินพวกเขา",
  ui_story_5037_50371101_79_dialog_content = "ด้วยวิธีนี้ แม้ว่าพวกเขาจะใส่ร้าย Vic ในบทความของพวกเขา การกล่าวอ้างของพวกเขาก็จะไม่มีหลักฐานที่แท้จริงใดๆ ที่จะสนับสนุนพวกเขา ซึ่งผู้คนจะสังเกตเห็นได้",
  ui_story_5037_50371101_80_dialog_content = "นอกจากนี้ ตราบเท่าที่วิคยังพัฒนาอยู่ การซุบซิบนินทาก็ไม่สามารถทำลายชื่อเสียงของเขาได้",
  ui_story_5037_50371101_81_dialog_content = "โอเค ฉันคิดว่าฉันเข้าใจแล้ว",
  ui_story_5037_50371101_82_dialog_content = "ขอขอบคุณ, PlayerName. คุณเป็นผู้ช่วยชีวิตจริงๆ!",
  ui_story_5037_50371101_83_dialog_content = "อย่าพูดถึงมัน เราอาจเป็นคู่แข่งกันชั่วคราว แต่เราจะเป็นเพื่อนกันเสมอ",
  ui_story_5037_50371101_84_dialog_content = "ฉันจะไม่มีวันปล่อยให้เรื่องเล็กน้อยอย่างการแข่งขันเข้ามาขัดขวางการช่วยเหลือเพื่อนของฉัน!",
  ui_story_5037_50371101_85_dialog_content = "*สะอื้น* นายคือฮีโร่ของฉันจริงๆ!",
  ui_story_5037_50371101_86_dialog_content = "ขอบคุณมาก, PlayerName!",
  ui_story_5037_50371101_87_dialog_content = "ฉันขอสาบานด้วยเกียรติของฉันในฐานะนักสัตววิทยาและไอดอลว่าฉันจะไม่ทำให้คุณผิดหวัง!",
  ui_story_5037_50371101_88_dialog_content = "เมื่อ Fia กำลังค้นคว้าเกี่ยวกับการเป็นโปรดิวเซอร์ เธอพบหนังสือสองเล่มที่คุณอาจพบว่ามีประโยชน์",
  ui_story_5037_50371101_89_dialog_content = "ไปข้างหน้าและเลือกหนึ่งในนั้น ถือว่าเป็นการแสดงความกตัญญูกตเวทีของเรา",
  ui_story_5037_50371101_90_dialog_content = "เดี๋ยวก่อน... นั่นไม่ใช่หนังสือของฉันเหรอ? ไม่แปลกใจเลยที่ข้าหาพวกมันไม่เจอตลอด... เจ้าซ่อนพวกมันไว้ในเสื้อผ้า!",
  ui_story_5037_50371101_91_dialog_content = "A-ยังไงก็ตาม ฉันได้อ่านทั้งคู่แล้ว ดังนั้นเลือกสิ่งที่คุณต้องการ PlayerName.",
  ui_story_5037_50371101_92_dialog_content = "ขอบคุณ... ฉันจะเอาอันนี้ไปก่อน—",
  ui_story_5037_50371101_93_option_content = "\"หลักสูตรเร่งรัดสำหรับไอดอลหน้าใหม่\"",
  ui_story_5037_50371101_94_option_content = "“การพัฒนาวิชาชีพสำหรับผู้ผลิตมืออาชีพ”",
  ui_story_5037_50371101_95_dialog_content = "ถูกต้อง! เราควรกลับไปฝึกได้แล้ว!",
  ui_story_5037_50371101_96_dialog_content = "ไปกันเถอะคุณนายผู้ไร้ค่า! ยังไม่หมดวัน!",
  ui_story_5037_50371101_97_dialog_content = "ฮ-ห๊ะ?! ยังคง?!",
  ui_story_5037_50371101_98_dialog_content = "ถูกตัอง! เราเสียเวลาอันมีค่ามากมายไปกับการพูดคุยกับ PlayerNameดังนั้นตอนนี้คุณจะต้องทำมันทั้งหมด!",
  ui_story_5037_50371101_99_dialog_content = "ใครก็ได้ช่วยฉันที... ได้โปรด...",
  ui_story_5037_50371201_1_dialog_content = "วิคบอกให้รอเขาที่นี่... เขาไม่รู้เหรอว่างานประกวดคอนเสิร์ตใกล้เข้ามาแล้ว?",
  ui_story_5037_50371201_2_dialog_content = "เขายังบอกให้ฉันมาที่นี่คนเดียวและเก็บเป็นความลับไม่ให้เฟีย...",
  ui_story_5037_50371201_3_dialog_content = "เขากำลังทำอะไรอยู่ตอนนี้?",
  ui_story_5037_50371201_4_dialog_content = "โอ้? ตรงเวลาอย่างที่ฉันคาดไว้! ยินดีที่ได้พบคุณ, PlayerName!",
  ui_story_5037_50371201_5_dialog_content = "เอาล่ะ วิค บอกฉันทีว่าเกิดอะไรขึ้น...",
  ui_story_5037_50371201_6_dialog_content = "โอ้ ไม่มีอะไรสำคัญมากจริงๆ! ฉันแค่อยากจะถามว่า...",
  ui_story_5037_50371201_7_dialog_content = "ให้ฉันซ่อนตัวที่นี่สักวันได้ไหม โปรด?!",
  ui_story_5037_50371201_8_dialog_content = "หา...?!",
  ui_story_5037_50371201_9_dialog_content = "ใกล้จะถึงเวลาคอนเสิร์ตแล้ว ทำไมคุณถึงมาหลบอยู่ที่นี่แทนที่จะไปซ้อมล่ะ?",
  ui_story_5037_50371201_10_dialog_content = "เป็นเพราะการฝึกของฉัน! แค่ฟัง นี่คือสิ่งที่ดูเหมือนวันธรรมดาสำหรับฉัน...",
  ui_story_5037_50371201_11_dialog_content = "เฟียปลุกฉันทุกเช้าเพื่อฝึกซ้อมก่อนที่ดวงอาทิตย์จะขึ้น",
  ui_story_5037_50371201_12_dialog_content = "ตื่นได้แล้ว อาจารย์จอมขี้เกียจ! ได้เวลาซ้อมแล้ว!",
  ui_story_5037_50371201_13_dialog_content = "เริ่มต้นด้วยการทุบร่างกายที่หย่อนยานให้เป็นรูปเป็นร่าง! สิบรอบป่า Go!",
  ui_story_5037_50371201_14_dialog_content = "ฮรือออออ...แต่ง่วงจัง...",
  ui_story_5037_50371201_15_dialog_content = "อีกห้านาที...",
  ui_story_5037_50371201_16_dialog_content = "ไม่ให้ความร่วมมือ? ฉันสบายดี... เอาตัวเขาไป Kylo!",
  ui_story_5037_50371201_17_dialog_content = "โล—!",
  ui_story_5037_50371201_18_dialog_content = "โอ๊ย!!!",
  ui_story_5037_50371201_19_dialog_content = "S-หยุดกัด! ฉันตื่น ฉันตื่น!!!",
  ui_story_5037_50371201_20_dialog_content = "หลังจากวิ่งเสร็จ ฉันไปอาบน้ำและรับประทานอาหารเช้าอย่างรวดเร็ว",
  ui_story_5037_50371201_21_dialog_content = "อาหารเช้าวันนี้เป็นขนมปังขี้เลื่อยกับแครอทต้มและนมหนึ่งแก้ว!",
  ui_story_5037_50371201_22_dialog_content = "B-แต่ฉันต้มแครอทมาสามวันแล้ว... เราเปลี่ยนอะไรนิดหน่อยไม่ได้เหรอ?",
  ui_story_5037_50371201_23_dialog_content = "เช่น ไส้เดือนย่างเสียบไม้ร้อนๆ เผ็ดร้อน?",
  ui_story_5037_50371201_24_dialog_content = "ตอนนี้คุณเป็นไอดอลแล้ว มาสเตอร์ และไอดอลต้องดูหุ่นตลอดเวลา! ถ้าคุณไม่ต้องการแครอทต้ม คุณก็โชคไม่ดี... ลองเดาสิว่ามื้อกลางวันและมื้อค่ำจะกินอะไรดี?",
  ui_story_5037_50371201_25_dialog_content = "ไม่นะ!",
  ui_story_5037_50371201_26_dialog_content = "โอ้ และ—",
  ui_story_5037_50371201_27_dialog_content = "เอ่อ... ฉันคิดว่าฉันได้ยินมามากพอแล้ว วิค...",
  ui_story_5037_50371201_28_dialog_content = "ด้วยเหตุนี้ เพื่อประโยชน์ต่อสุขภาพและสติของฉัน ฉันขอร้องคุณ PlayerName... ขอหลบอยู่ที่นี่สักวันเถอะ!",
  ui_story_5037_50371201_29_dialog_content = "แค่วันเดียวก็เกินพอ! ไม่มี Aurorian ควรจะเคยผ่านนรกแบบนี้!",
  ui_story_5037_50371201_30_dialog_content = "หากยังเป็นเช่นนี้ต่อไป โลกจะสูญเสียนักสัตววิทยาที่ยิ่งใหญ่ที่สุดไปในทันที!",
  ui_story_5037_50371201_31_dialog_content = "คุณ... ฉัน... เฮ้อ...",
  ui_story_5037_50371201_32_dialog_content = "ฉันรู้ว่า Fia ทำสิ่งนี้เพื่อช่วยให้คุณผ่านการประกวดคอนเสิร์ตเท่านั้น แต่ระเบียบการฝึกซ้อมของเธอดูจะ...เข้มงวดไปหน่อย",
  ui_story_5037_50371201_33_dialog_content = "คุณสามารถอยู่ที่นี่และพักผ่อนได้เล็กน้อย แต่มีเงื่อนไขเพียงสองข้อ—",
  ui_story_5037_50371201_34_dialog_content = "หนึ่ง คุณต้องกลับไปหา Fia ทันทีที่คุณพักผ่อน เพื่อไม่ให้เธอเป็นห่วงคุณ",
  ui_story_5037_50371201_35_dialog_content = "และสอง... คุณต้องคุยกับ Fia อย่างจริงจังเกี่ยวกับความรู้สึกของคุณที่มีต่อระบบการฝึกของเธอ",
  ui_story_5037_50371201_36_dialog_content = "ไม่ใช่ปัญหา! ตราบใดที่ฉันสามารถสูญเสียได้ เอ่อ... ฉันหมายถึง ลดความเหนื่อยล้านี้ลงบ้าง ฉันจะทำทุกอย่างที่คุณต้องการ!",
  ui_story_5037_50371201_37_dialog_content = "เอาล่ะ พักผ่อนบ้างนะวิค ฉันยังต้องร่างตารางของโกลดี้สำหรับวันนี้ ดังนั้นฉันจะปล่อยให้คุณอยู่คนเดียว",
  ui_story_5037_50371201_38_dialog_content = "ใช่ ใช่ ลุยเลย! ฉันจะสบายดีด้วยตัวฉันเอง!",
  ui_story_5037_50371201_39_dialog_content = "โซฟาตัวนี้ดูสบายมาก... เหมาะสำหรับการงีบหลับยาว!",
  ui_story_5037_50371201_40_dialog_content = "เอาล่ะ เจ้าขนฟูตัวน้อยของฉัน มานี่สิ ให้ฉันกอดคุณตอนฉันหลับ!",
  ui_story_5037_50371201_41_dialog_content = "จิ๊บ!",
  ui_story_5037_50371201_42_dialog_content = "กรน...กรน...",
  ui_story_5037_50371201_43_dialog_content = "(เขาหลับไปแล้วเหรอ นั่นวิคสำหรับคุณ ฉันเดาว่า...)",
  ui_story_5037_50371201_44_dialog_content = "(อืม ฉันควรกลับไปทำงานได้แล้ว)",
  ui_story_5037_50371201_45_dialog_content = "<color=#828282>ในเวลาต่อมา</color>",
  ui_story_5037_50371201_46_dialog_content = "(เอาล่ะ นั่นควรทำตามตาราง! ฉันคิดว่าฉันเริ่มจะชินกับสิ่งนี้แล้ว!)",
  ui_story_5037_50371201_47_dialog_content = "<color=#828282>ก๊อกก๊อก!</color>",
  ui_story_5037_50371201_48_dialog_content = "(หืม? มีคนอยู่ที่ประตู...)",
  ui_story_5037_50371201_49_dialog_content = "สวัสดีครับ",
  ui_story_5037_50371201_50_dialog_content = "สวัสดี PlayerName! ฉันเองเฟีย!",
  ui_story_5037_50371201_51_dialog_content = "(ฟ-เฟีย?!)",
  ui_story_5037_50371201_52_dialog_content = "(ไม่นะ... วิคยังอยู่!)",
  ui_story_5037_50371201_53_dialog_content = "<color=#828282>ก๊อกก๊อก!</color>",
  ui_story_5037_50371201_54_dialog_content = "PlayerName?",
  ui_story_5037_50371201_55_dialog_content = "J-เดี๋ยวก่อน!",
  ui_story_5037_50371201_56_dialog_content = "วิค! ตื่นได้แล้ว วิค!",
  ui_story_5037_50371201_57_dialog_content = "งืง... ฮ่าๆ... หยุดนะเจ้าขนปุยน้อย... ฮ่าฮ่าฮ่า...",
  ui_story_5037_50371201_58_dialog_content = "เขานอนหนักกว่าฉันอีก!",
  ui_story_5037_50371201_59_dialog_content = "(เดาว่าช่วยไม่ได้...ฉันคงต้องซ่อนเขาไว้ก่อนแล้ว)",
  ui_story_5037_50371201_60_dialog_content = "(ขอดูหน่อย...นิตยสารกองนี้ดูดี ฉันจะซ่อนเขาไว้ข้างหลัง!)",
  ui_story_5037_50371201_61_dialog_content = "มาเฟีย!",
  ui_story_5037_50371201_62_dialog_content = "อะไรทำให้คุณใช้เวลานานมาก?",
  ui_story_5037_50371201_63_dialog_content = "S-ขอโทษ ฉันแค่เอ่อ... ทำความสะอาดห้อง!",
  ui_story_5037_50371201_64_dialog_content = "ดูเหมือนว่าสถานที่นี้น่าจะช่วยจัดระเบียบได้บ้าง... นิตยสารกองโตเท่าภูเขา!",
  ui_story_5037_50371201_65_dialog_content = "อะฮ่า...ฮ่า... เอาล่ะ คุณต้องการอะไรไหม เฟีย?",
  ui_story_5037_50371201_66_dialog_content = "ใช่ ที่จริง... ช่วงนี้คุณเห็นมาสเตอร์วิคแถวนี้ไหม?",
  ui_story_5037_50371201_67_dialog_content = "วี-วิก? ไม่ ไม่สามารถพูดได้ว่าฉันมี!",
  ui_story_5037_50371201_68_dialog_content = "ไม่บอก...?",
  ui_story_5037_50371201_69_dialog_content = "วันนี้ฉันทำความสะอาดทั้งวัน รวมทั้งทำงานตามตารางของโกลดี้ด้วย... ไม่สิ วันนี้ฉันไม่เห็นวิคเลย!",
  ui_story_5037_50371201_70_dialog_content = "เฮ้อ...ถ้าจะว่าอย่างนั้น ฉันแปลกใจจริงๆ ที่เขาไม่วิ่งมาหาคุณก่อน...",
  ui_story_5037_50371201_71_dialog_content = "นายที่แสนดีของฉันหนีไปไหน...?",
  ui_story_5037_50371201_72_dialog_content = "บางทีเขาอาจจะไปที่ไหนสักแห่งเพื่อผ่อนคลายสักหน่อย? ฉันแน่ใจว่าเขาจะกลับมาเร็วพอ",
  ui_story_5037_50371201_73_dialog_content = "คอนเสิร์ตเหลืออีกไม่กี่วันแล้ว...ไม่อยากจะเชื่อเลยว่าผู้ชายคนนั้นยังคิดจะทำอะไรบ้าๆ บอๆ แบบนี้ได้อีก",
  ui_story_5037_50371201_74_dialog_content = "ฉันจะฝึกเขาให้หนักเป็นพิเศษเมื่อเขากลับมา...",
  ui_story_5037_50371201_75_dialog_content = "ฉัน-เป็นไปได้ไหมว่าการฝึกของคุณอาจทำให้เขาหนีไป เฟีย?",
  ui_story_5037_50371201_76_dialog_content = "การฝึกอย่างจริงจังก็เป็นเรื่องปกติ... แต่คุณต้องจำไว้ว่าให้สมดุลกับการพักผ่อนด้วยเช่นกัน",
  ui_story_5037_50371201_77_dialog_content = "คุณคิด?",
  ui_story_5037_50371201_78_dialog_content = "รู้ไหม ฉันกำลังคิดว่าจะให้เขาหยุดหนึ่งวัน เพื่อที่เขาจะได้พักผ่อน...",
  ui_story_5037_50371201_79_dialog_content = "แต่แล้วจู่ๆ เขาก็หายไปจากตัวฉัน! ฉันค้นหาทั่ว Umbraton แต่ก็ยังไม่มีวี่แววของเขา",
  ui_story_5037_50371201_80_dialog_content = "(เฟียวางแผนที่จะให้วิคหยุดงานหนึ่งวัน? ดังนั้นเธอจึงจัดตารางเวลาของเขาอย่างเหมาะสม)",
  ui_story_5037_50371201_81_dialog_content = "ไม่ต้องห่วงเฟีย ฉันจะขอให้ทุกคนช่วยตามหาเขา",
  ui_story_5037_50371201_82_dialog_content = "แน่นอนขอบคุณ. ฉันจะค้นหาต่อไป",
  ui_story_5037_50371201_83_dialog_content = "เดี๋ยวก่อน... นั่นสินะ...?",
  ui_story_5037_50371201_84_dialog_content = "(บ้าจริง! เธอสังเกตเห็นกองนิตยสารที่วิกซ่อนไว้!)",
  ui_story_5037_50371201_85_dialog_content = "โอ้! S-ขออภัย นี่เป็นเพียงนิตยสารบางส่วนที่ฉันอ่านไปก่อนหน้านี้! ฉันจะทำความสะอาดพวกมันในไม่ช้า—",
  ui_story_5037_50371201_86_dialog_content = "มันดูตลกใช่มั้ยล่ะ? ราวกับว่ามีอะไรฝังอยู่ข้างใต้นั้น...",
  ui_story_5037_50371201_87_dialog_content = "ไม่รอ-!",
  ui_story_5037_50371201_88_dialog_content = "อ-อาจารย์?!",
  ui_story_5037_50371201_89_dialog_content = "กรน...กรน...",
  ui_story_5037_50371201_90_dialog_content = "ทะ-เขามานอนทำอะไรที่นี่?!",
  ui_story_5037_50371201_91_dialog_content = "PlayerName... คุณโกหกฉันหรือเปล่า?",
  ui_story_5037_50371201_92_dialog_content = "ฉัน เอ่อ...",
  ui_story_5037_50371201_93_option_content = "สารภาพ",
  ui_story_5037_50371201_94_dialog_content = "เอาล่ะ ฉันสารภาพ... ฉันโกหกคุณก่อนหน้านี้",
  ui_story_5037_50371201_95_dialog_content = "โทษที...",
  ui_story_5037_50371201_96_dialog_content = "ไม่เป็นไร, PlayerName. ฉันรู้ว่าคุณจะไม่โกหกฉันโดยเจตนา",
  ui_story_5037_50371201_97_option_content = "สร้างบางสิ่งบางอย่างขึ้น",
  ui_story_5037_50371201_98_dialog_content = "ฮ-เขาต้องแอบเข้ามาที่นี่ก่อนที่ฉันมาถึง! ใช่ ต้องเป็นอย่างนั้น...",
  ui_story_5037_50371201_99_dialog_content = "ฉันบอกได้เลยว่าคุณกำลังโกหก PlayerName... มันเขียนเต็มใบหน้าของคุณ",
  ui_story_5037_50371201_100_dialog_content = "แต่ฉันคิดว่าฉันรู้ว่าเกิดอะไรขึ้นที่นี่",
  ui_story_5037_50371201_101_dialog_content = "อาจารย์ผู้ไร้ค่าของฉันขอร้องให้คุณปล่อยให้เขาอยู่ที่นี่ ใช่ไหม",
  ui_story_5037_50371201_102_dialog_content = "ความจริงก็คือ...",
  ui_story_5037_50371201_103_dialog_content = "วิคมาหาฉันเมื่อเช้านี้และถามว่าเขาจะซ่อนตัวที่นี่และพักผ่อนในวันนี้ได้ไหม",
  ui_story_5037_50371201_104_dialog_content = "เขาบอกว่าการฝึกไอดอลของเขาทำให้เขาหมดแรง และไม่นานหลังจากที่เขามาถึงที่นี่ เขาก็สลบไป",
  ui_story_5037_50371201_105_dialog_content = "แต่ฉันไม่เข้าใจ! ทำไมเขาถึงวิ่งหนีไปหาคุณแทนที่จะคุยกับฉัน",
  ui_story_5037_50371201_106_dialog_content = "ฉันวางแผนที่จะให้วันหยุดและทุกอย่างกับเขา!",
  ui_story_5037_50371201_107_dialog_content = "ทำไมคุณไม่พูดอะไรกับเขาเมื่อเขาตื่นขึ้น?",
  ui_story_5037_50371201_108_dialog_content = "เฮ้อ...ลืมไปเลย ฉันจะปล่อยให้เขาพักผ่อนที่นี่ในตอนนี้",
  ui_story_5037_50371201_109_dialog_content = "เตือนเขาให้กลับมาฝึกซ้อมเมื่อตื่นขึ้น โอเค?",
  ui_story_5037_50371201_110_dialog_content = "ฉันจะรวบรวมเคล็ดลับและเทคนิคสำหรับการฝึกฝนไอดอลเพื่อแบ่งปันกับคุณในภายหลัง ใช้มันเป็นวิธีการกล่าวขอบคุณที่เฝ้าดูเจ้านายผู้ไร้ค่าของฉัน",
  ui_story_5037_50371201_111_dialog_content = "แน่นอนขอบคุณ!",
  ui_story_5037_50371201_112_dialog_content = "อ้อ และอย่างสุดท้าย... อย่าบอกเขาว่าฉันมาที่นี่ เข้าใจไหม?",
  ui_story_5037_50371201_113_dialog_content = "แน่นอน แต่ทำไม",
  ui_story_5037_50371201_114_dialog_content = "เพราะว่า...",
  ui_story_5037_50371201_115_dialog_content = "<size=45>อาจารย์ไม่น่าไว้วางใจอย่างยิ่ง!</size>",
  ui_story_5037_50371201_116_dialog_content = "หา?!",
  ui_story_5037_50371201_117_dialog_content = "ถ้าคุณให้เขาหนึ่งนิ้ว เขาจะใช้เวลาหนึ่งไมล์ก่อนที่คุณจะรู้ตัว!",
  ui_story_5037_50371201_118_dialog_content = "ไม่ว่าจะเป็นการฝึกซ้อมหรือแม้กระทั่งแค่ทำสิ่งต่างๆ ในบ้าน เขาจะหาข้อแก้ตัวเพิ่มเติมเพื่อผ่อนคลายหากเขารู้ว่าฉันจะให้เขาหยุดพัก",
  ui_story_5037_50371201_119_dialog_content = "สำหรับคนอย่างเขา วิธีเดียวที่จะทำให้พวกเขาร่วมมือคือการเข้มงวดอย่างไร้ความปราณี!",
  ui_story_5037_50371201_120_dialog_content = "คะ-ครับ!",
  ui_story_5037_50371201_121_dialog_content = "ฉันจะส่งเขากลับไปฝึกทันทีที่เขาตื่น!",
  ui_story_5037_50371301_1_dialog_content = "ทำไมสิ่งนี้ต้องเกิดขึ้นตอนนี้ตลอดเวลา?",
  ui_story_5037_50371301_2_dialog_content = "ก็ไม่เห็นมีปัญหานี่ครับ...",
  ui_story_5037_50371301_3_dialog_content = "มีเพียงปรมาจารย์ไร้ค่าอย่างเจ้าเท่านั้นที่จะพูดเช่นนั้นในเวลาเช่นนี้!",
  ui_story_5037_50371301_4_dialog_content = "สถานการณ์นี้เลวร้ายจริงหรือ?",
  ui_story_5037_50371301_5_dialog_content = "แย่หน่อยที่มันน่าจะเป็นอย่างนั้น...",
  ui_story_5037_50371301_6_dialog_content = "เรากำลังมีปัญหาร้ายแรงในขณะนี้ ทุกคน!",
  ui_story_5037_50371301_7_dialog_content = "ไม่ว่าเราจะพยายามมากแค่ไหน... ความคืบหน้าของ Goldie และ Vic ก็เริ่มช้าลง!",
  ui_story_5037_50371301_8_dialog_content = "นี่คือสิ่งที่พวกเขาเรียกว่า \"ที่ราบสูง\" ที่น่ากลัว!",
  ui_story_5037_50371301_9_dialog_content = "ฉันกับเฟียคิดวิธีแก้ปัญหาที่ไม่เหมือนใครเพื่อที่เราจะได้ตระหนักถึงศักยภาพสูงสุดของเราก่อนคอนเสิร์ตจบการศึกษา!",
  ui_story_5037_50371301_10_dialog_content = "เราจะเปลี่ยนผู้ผลิต!",
  ui_story_5037_50371301_11_dialog_content = "หา?!",
  ui_story_5037_50371301_12_dialog_content = "ถูกตัอง! คุณจะฝึกปรมาจารย์ผู้ไร้ค่าของฉัน PlayerName! ในขณะเดียวกัน ฉันจะทำงานร่วมกับโกลดีในการฝึกของเธอ!",
  ui_story_5037_50371301_13_dialog_content = "เตรียมตัวให้พร้อมสำหรับโปรแกรมแลกเปลี่ยนการฝึกอบรมหนึ่งวันที่น่าตื่นเต้น!",
  ui_story_5037_50371301_14_dialog_content = "ด้วยผู้ผลิตรายใหม่ สูตรการฝึกอบรมใหม่ และสภาพแวดล้อมใหม่สำหรับทุกคนที่เกี่ยวข้อง... ฉันแน่ใจว่าเราจะได้พบกับแรงบันดาลใจใหม่และน่าตื่นเต้นเพื่อทะลวงผ่านที่ราบสูงของเรา!",
  ui_story_5037_50371301_15_dialog_content = "หมายความว่า... ฉันจะรับผิดชอบการฝึก Vic เหรอ?",
  ui_story_5037_50371301_16_dialog_content = "โอ๊ะ! ฟังดูเป็นความคิดที่ดีสำหรับฉัน! บางทีฉันอาจจะทำใจให้สบายได้สักพัก...",
  ui_story_5037_50371301_17_dialog_content = "โอ๊ย โอ๊ย! นั่นคือเท้าของฉัน Fia!",
  ui_story_5037_50371301_18_dialog_content = "เราก็คิดอย่างนั้นเหมือนกัน อาจารย์ เอาล่ะ PlayerName; Kyllo จะเป็นผู้ช่วยของคุณในการแลกเปลี่ยนการฝึกอบรม",
  ui_story_5037_50371301_19_dialog_content = "โล?",
  ui_story_5037_50371301_20_dialog_content = "และอย่ากังวลไป Kyllo รู้ดีว่าต้องทำอย่างไรหาก Master เมินเฉยหรือไม่ยอมลุกจากเตียง... ใช่ไหม Kyllo?",
  ui_story_5037_50371301_21_dialog_content = "คุณคิดทุกอย่างจริงๆ เฟีย...",
  ui_story_5037_50371301_22_dialog_content = "เอาล่ะ เป็นอันเรียบร้อย!",
  ui_story_5037_50371301_23_dialog_content = "พยายามอย่างเต็มที่เพื่อช่วยวิคเหมือนที่คุณทำกับฉัน โอเค PlayerName?",
  ui_story_5037_50371301_24_dialog_content = "ฉันรู้ว่าคุณจะทำได้ดีมาก!",
  ui_story_5037_50371301_25_dialog_content = "แน่นอน ปล่อยให้เป็นหน้าที่ของผม",
  ui_story_5037_50371301_26_dialog_content = "เราจะไปกันแล้ว! โชคดีนะคุณสองคน!",
