  ui_story_5037_50371301_28_dialog_content = "โอ๊ย!!!",
  ui_story_5037_50371301_29_dialog_content = "ปล่อยนะ Kyllo! ขาไม่มีไว้กิน!!!",
  ui_story_5037_50371301_30_dialog_content = "โล?",
  ui_story_5037_50371301_31_dialog_content = "ว้าว... Kyllo สามารถบอกได้แม้กระทั่งเมื่อคุณคิดจะเลิกเล่น Vic ค่อนข้างน่าประทับใจ",
  ui_story_5037_50371301_32_dialog_content = "เฮ้อ... Fia ทำให้คุณต่อต้านฉันจริงๆ ใช่ไหม Kyllo?",
  ui_story_5037_50371301_33_dialog_content = "ท้ายที่สุดฉันก็ทำเพื่อคุณเช่นกัน! เลี้ยงคุณตั้งแต่แรกเกิด ให้คุณมีทางรอดในโลก...",
  ui_story_5037_50371301_34_dialog_content = "อุ—ช!!!",
  ui_story_5037_50371301_35_dialog_content = "ดูเหมือนว่า Kyllo จะหมายถึงธุรกิจ วิค... เราควรเริ่มฝึกกัน",
  ui_story_5037_50371301_36_dialog_content = "*สะอื้น* ทำไมฉันถึงเป็นฝ่ายเจ็บตลอด...?",
  ui_story_5037_50371301_37_dialog_content = "ไม่ต้องกังวลวิค ฉันจัดสมดุลระหว่างการทำงานและการพักผ่อนกับการฝึก ดังนั้นคุณน่าจะสบายดี",
  ui_story_5037_50371301_38_dialog_content = "วาระแรกในวันนี้คือการฝึกออกเสียง",
  ui_story_5037_50371301_39_dialog_content = "<color=#828282>ในเวลาต่อมา</color>",
  ui_story_5037_50371301_40_dialog_content = "♪ อา ฤดูใบไม้ผลิมาถึงแล้ว และทุกอย่างกลับมามีชีวิตชีวาอีกครั้ง! ♪",
  ui_story_5037_50371301_41_dialog_content = "♪ สัตว์ต่างๆ ขึ้นมาจากโพรงและถ้ำของพวกมัน ♪",
  ui_story_5037_50371301_42_dialog_content = "♪ ในป่าและในทุ่งหญ้า ♪",
  ui_story_5037_50371301_43_dialog_content = "เอาล่ะ คุณไปพักได้แล้ว วิค",
