  ui_story_5037_50371301_45_dialog_content = "โล...",
  ui_story_5037_50371301_46_dialog_content = "ฉันไม่หย่อนเวลานี้ Kyllo! นี่เป็นการหยุดพักอย่างแท้จริงและซื่อสัตย์!",
  ui_story_5037_50371301_47_dialog_content = "เฮ้ วิค? ฉันอยากจะถาม... อะไรทำให้คุณอยากเป็นไอดอลตั้งแต่แรก?",
