  ui_story_5037_50371301_49_dialog_content = "หา?",
  ui_story_5037_50371301_50_dialog_content = "ก่อนอื่น ฉันไม่ใช่ไอดอล ฉันเป็นนักสัตววิทยาและจะเป็นตลอดไป!",
  ui_story_5037_50371301_51_dialog_content = "แข่งอะไรกันเนี่ย!",
  ui_story_5037_50371301_52_dialog_content = "เพื่อสร้างรายได้ชัดๆ!",
  ui_story_5037_50371301_53_dialog_content = "คุณอยู่ในนั้น ... เพื่อเงินรางวัล?",
  ui_story_5037_50371301_54_dialog_content = "ฉันหมายความว่า ฉันรู้ว่า Lady Sheol เสนอรางวัลก้อนโต และฉันรู้ว่าสถานการณ์ทางการเงินของคุณค่อนข้างแย่...",
  ui_story_5037_50371301_55_dialog_content = "แต่ทำไมฟีอาต้องเกี่ยวข้องด้วย?",
  ui_story_5037_50371301_56_dialog_content = "มันเป็นความคิดของเฟียตั้งแต่แรก! เธอเห็นโปสเตอร์การประกวดและตัดสินใจลากฉันเข้าร่วมโครงร่างของเธอ...",
  ui_story_5037_50371301_57_dialog_content = "เรามีเงินทุนเหลือน้อยสำหรับการดูแลสัตว์มหัศจรรย์ของเรา...",
  ui_story_5037_50371301_58_dialog_content = "ต่ำแค่ไหน?",
  ui_story_5037_50371301_59_dialog_content = "ก็... ฉันต้องเป็นหนี้นิดหน่อยเพื่อซื้อขนม Bica และ Drakolion...",
  ui_story_5037_50371301_60_dialog_content = "แย่ขนาดนั้นเลย?!",
  ui_story_5037_50371301_61_dialog_content = "เดี๋ยวก่อน... คุณไม่ควรส่งต่อขนมเพื่อประหยัดเงินหากเกิดเรื่องแย่ขนาดนั้น?",
  ui_story_5037_50371301_62_dialog_content = "ไม่มีโอกาส!",
  ui_story_5037_50371301_63_dialog_content = "สัตว์มหัศจรรย์เหล่านั้นเป็นเพื่อนของฉัน ฉันไม่สามารถอยู่กับตัวเองได้หากพวกเขาต้องไปโดยปราศจากสิ่งอำนวยความสะดวกจากสิ่งมีชีวิต!",
  ui_story_5037_50371301_64_dialog_content = "โดยปกติแล้ว Fia และ Shira จะทำเงินได้จากการทำงานแปลกๆ ระหว่างโครงการวิจัยของพวกเขา เราจึงไม่ต้องกังวลเกี่ยวกับการเป็นหนี้",
  ui_story_5037_50371301_65_dialog_content = "แต่ในระหว่างการเดินทางครั้งสุดท้ายของ Fia เธอใช้เวลาอันน่าเหลือเชื่อในการสืบสวนสัตว์มหัศจรรย์หายาก แต่กลับไม่พบผลลัพธ์ที่น่าสังเกตใดๆ",
  ui_story_5037_50371301_66_dialog_content = "และเช่นเดียวกัน เงินเก็บของเราก็หมดลง และฉันต้องยืมเงินก้อนหนึ่ง!",
  ui_story_5037_50371301_67_dialog_content = "... ฉันขอถามได้ไหมว่าคุณกำลังทำอะไรในขณะที่เธอไม่อยู่?",
  ui_story_5037_50371301_68_dialog_content = "ผม? ตามธรรมชาติแล้ว ฉันกำลังดูแลสัตว์วิเศษและประหยัดพลังงานด้วยการงีบหลับให้เพียงพอ...",
  ui_story_5037_50371301_69_dialog_content = "ดูเหมือนว่าคุณไม่ได้พยายามช่วยเลย!",
  ui_story_5037_50371301_70_dialog_content = "ทันใดนั้น ฉันรู้สึกว่าฉันเข้าใจการต่อสู้ของ Fia และ Shira มากขึ้น...",
  ui_story_5037_50371301_71_dialog_content = "ตอนนี้ฉันกำลังทำเงินอยู่ใช่ไหม ฉันยังเห็นด้วยกับการแสดงงี่เง่าพวกนี้!",
  ui_story_5037_50371301_72_dialog_content = "ฉันทำงานหนักมากจนถึงตอนนี้!",
  ui_story_5037_50371301_73_dialog_content = "ฉันรู้ ฉันรู้... พูดตามตรง ฉันคาดหวังให้คุณเลิกกลางคันและพยายามหาทางออกจากสิ่งนี้",
  ui_story_5037_50371301_74_dialog_content = "ฉันจะไม่ทำสิ่งนั้น! โดยเฉพาะอย่างยิ่งเมื่อต้องทำให้แน่ใจว่าสัตว์ร้ายมีเพียงพอกิน!",
  ui_story_5037_50371301_75_dialog_content = "ฉันจะทำทุกอย่างเพื่อคนเหล่านั้น",
  ui_story_5037_50371301_76_dialog_content = "และนั่นคือเหตุผลที่ฉันยินดีที่จะให้ลูกศิษย์ของฉันยืมคุณสำหรับทุกสิ่งที่คุณต้องการ! ตราบใดที่คุณจ่ายแน่นอน",
  ui_story_5037_50371301_77_dialog_content = "ลืมไปเลย วิค! อย่าทำให้ชีวิตสองคนนั้นยากไปกว่านี้เลย!",
  ui_story_5037_50371301_78_dialog_content = "ฉันสาบานเลย บางครั้งรู้สึกเหมือนคุณสนใจเจ้าขนฟูตัวน้อยมากกว่าที่คุณสนใจ Fia และ Shira...",
  ui_story_5037_50371301_79_dialog_content = "คุณไม่ผิดไปกว่านี้แล้ว! คำพูดไม่สามารถอธิบายได้ว่าฉันภูมิใจในตัวลูกศิษย์ที่รักของฉันแค่ไหน!",
  ui_story_5037_50371301_80_dialog_content = "ไม่เพียงแต่ฉันได้ถ่ายทอดความเชี่ยวชาญด้านสัตววิทยาทั้งหมดของฉันให้กับพวกเขาแล้ว... พวกเขายังรู้วิธีหาเงินและเอาตัวรอดในโลกนี้ด้วย!",
  ui_story_5037_50371301_81_dialog_content = "ยิ่งไปกว่านั้น ทั้งคู่ไม่กลัวที่จะต่อสู้กับ Eclipsites!",
  ui_story_5037_50371301_82_dialog_content = "สักวันหนึ่ง ฉันจะสามารถมอบโครงการวิจัยทั้งหมดของฉันเกี่ยวกับสัตว์มหัศจรรย์ของ Astra ให้พวกเขาได้...",
  ui_story_5037_50371301_83_dialog_content = "คุณจะทำอย่างไร งีบหลับมากขึ้น?",
  ui_story_5037_50371301_84_dialog_content = "ไม่ใช่ความคิดที่ดี! ฉันจะพิจารณามันอย่างแน่นอน!",
  ui_story_5037_50371301_85_dialog_content = "แต่ก่อนหน้านั้น ฉันยังมีงานสำคัญอีกมากที่ต้องทำ",
  ui_story_5037_50371301_86_dialog_content = "ฉันเชื่อว่ามีทวีปอื่นเช่น Astra ในโลกของเรา",
  ui_story_5037_50371301_87_dialog_content = "ฉันต้องการเห็นพวกมันทั้งหมดและเรียนรู้ทุกสิ่งที่ควรรู้เกี่ยวกับสัตว์ร้ายที่อาศัยอยู่ในดินแดนของพวกมัน!",
  ui_story_5037_50371301_88_dialog_content = "ไม่นึกเลยว่าเจ้าจะมีความฝันที่ยิ่งใหญ่เช่นนี้...",
