  ui_story_5037_50371301_90_dialog_content = "โอ๊ย!!!",
  ui_story_5037_50371301_91_dialog_content = "ความคิดที่ยิ่งใหญ่คืออะไร Kylo?!",
  ui_story_5037_50371301_92_dialog_content = "ดูเหมือนว่า Kyllo กำลังเตือนคุณว่าพักของคุณจบแล้ว Vic กลับไปฝึกซ้อม!",
  ui_story_5037_50371301_93_dialog_content = "Fia มีอิทธิพลต่อคุณมากจริงๆ ใช่ไหม Kyllo? คุณรุนแรงกว่าที่เป็นอยู่ตอนนี้!",
  ui_story_5037_50371301_94_dialog_content = "แต่ตั้งแต่ PlayerName เป็นผู้รับผิดชอบการฝึกของฉันในวันนี้ บางทีเขาอาจจะขยายเวลาพักของฉันออกไปอีกสองสามนาที คุณว่าอย่างไร?",
  ui_story_5037_50371301_95_dialog_content = "อืมม...",
  ui_story_5037_50371301_96_dialog_content = "มาเร็ว! ฉันจะให้คุณเลี้ยงเจ้าขนฟูตัวน้อยไปด้วยในระหว่างนี้!",
  ui_story_5037_50371301_97_dialog_content = "ถ้าพูดแบบนั้น ผมว่าเรา...",
