  ui_story_5037_50371301_104_dialog_content = "ตามธรรมชาติแล้วสิ่งนี้จะช่วยให้คุณปรับปรุงได้",
  ui_story_5037_50371301_105_dialog_content = "เราไม่สามารถปล่อยให้การทำงานหนักทั้งหมดของ Fia เสียเปล่าได้ ดังนั้นเราจะฝึกฝนจิตใจของเราให้เต็มที่! คุณพร้อมวิค?",
