  ui_story_5037_50371401_4_dialog_content = "งั้นเหรอ...",
  ui_story_5037_50371401_5_dialog_content = "ถ้าอย่างนั้นเรามาเริ่มเวิร์กชอปหลักสูตรความผิดพลาดครั้งแรกของผู้ผลิตกันเลย",
  ui_story_5037_50371401_6_dialog_content = "...",
