  ui_story_5037_50371401_8_dialog_content = "(Vice และ Carleen นำสิ่งเหล่านี้มาในการประชุมเชิงปฏิบัติการจริงๆ หรือ?)",
  ui_story_5037_50371401_9_dialog_content = "(พวกเขาดูจริงจังมาก... ฉันมีความรู้สึกไม่ดีเกี่ยวกับเรื่องนี้...)",
