  ui_story_5037_50371401_12_dialog_content = "อย่างแท้จริง. เมื่อพูดถึงความสำเร็จของคุณ เราจะประมาทไม่ได้",
  ui_story_5037_50371401_13_dialog_content = "ขอบคุณที่เป็นห่วง แต่ฉันเป็นคนรับผิดชอบเรื่องนั้น ไม่ใช่คุณสองคน...",
  ui_story_5037_50371401_14_dialog_content = "คุณกำลังพูดถึงอะไร เราเป็นหุ้นส่วนกันไม่ใช่เหรอ? เราจะอยู่เคียงข้างคุณเสมอ!",
  ui_story_5037_50371401_15_dialog_content = "และเพื่อช่วยให้คุณเข้าใจอาชีพใหม่ของคุณมากที่สุดเท่าที่จะเป็นไปได้ Vice และฉันได้ทำการวิจัยร่วมกัน",
  ui_story_5037_50371401_16_dialog_content = "ถูกตัอง! ทุกสิ่งที่คุณต้องการเรียนรู้ตั้งแต่การเป็นไอดอลไปจนถึงการเป็นโปรดิวเซอร์อยู่ในหนังสือเหล่านี้แล้ว!",
  ui_story_5037_50371401_17_dialog_content = "ตั้งแต่วันนี้เป็นต้นไป เวิร์คช็อปของ Producer's Crash Course จะเป็นที่จัดขึ้น!",
  ui_story_5037_50371401_18_dialog_content = "เดี๋ยวก่อน... นี่คือบันทึกและคลิปบทความทั้งหมด ?!",
  ui_story_5037_50371401_19_dialog_content = "ได้! คาร์ลีนไปที่ห้องสมุดและจดบันทึกในหนังสือทุกเล่มที่เกี่ยวข้องกับกฎการฝึกสำหรับนักร้องและนักเต้น",
  ui_story_5037_50371401_20_dialog_content = "ในขณะเดียวกัน ฉันซื้อสำเนาของหนังสือพิมพ์ทุกฉบับที่ตีพิมพ์ในช่วงไม่กี่ปีที่ผ่านมาและตัดทุกอย่างที่เกี่ยวข้องกับไอดอลและโปรดิวเซอร์ออก!",
  ui_story_5037_50371401_21_dialog_content = "ที่น่ากลัวน่าประทับใจ...",
  ui_story_5037_50371401_22_dialog_content = "ต้องใช้เวลาหลายวันกว่าจะอ่านหนังสือทั้งหมดและเขียนบันทึกเหล่านี้ได้...",
  ui_story_5037_50371401_23_dialog_content = "ฉันได้รับความช่วยเหลือจาก Chloe และ Keating ระหว่างการวิจัยของฉัน",
  ui_story_5037_50371401_24_dialog_content = "ทั้งคู่รู้เรื่องดนตรีมากกว่าฉันมาก ดังนั้นพวกเขาจึงเขียนโน้ตเหล่านี้เป็นส่วนใหญ่",
