  ui_story_5037_50371401_26_dialog_content = "ในฐานะนักข่าวมืออาชีพ เธอคุ้นเคยกับข่าวและกิจกรรมทุกประเภทเป็นอย่างดี!",
  ui_story_5037_50371401_27_dialog_content = "ใช่ ทั้งหมดนี้จะเกิดขึ้นไม่ได้เลยหากปราศจากความช่วยเหลือจากทุกคน",
  ui_story_5037_50371401_28_dialog_content = "ไม่ได้ล้อเล่น...",
  ui_story_5037_50371401_29_dialog_content = "ดูเหมือนว่าฉันไม่สามารถหย่อนได้! ทุกคนคาดหวังกับฉันมาก!",
