  ui_story_5037_50371401_31_dialog_content = "ลำดับต่อไปของธุรกิจคือการตัดสินใจเกี่ยวกับแผนการฝึกอบรมสำหรับคุณ PlayerName!",
  ui_story_5037_50371401_32_dialog_content = "แผนการฝึกซ้อม?",
  ui_story_5037_50371401_33_dialog_content = "ใช่. เราได้พัฒนาแผนการฝึกอบรมที่แตกต่างกัน 2 แผนสำหรับคุณ เราจะให้คุณตัดสินใจว่าอันไหนเหมาะสมกว่ากัน",
