  ui_story_5037_50371401_36_dialog_content = "ประกอบด้วยความรู้ที่มีตั้งแต่ระดับพื้นฐานไปจนถึงระดับมืออาชีพ อย่างไรก็ตามเนื้อหามีความหนาแน่นและต้องใช้เวลาในการศึกษามากขึ้น",
  ui_story_5037_50371401_37_dialog_content = "แล้วอีกอย่าง...?",
  ui_story_5037_50371401_38_dialog_content = "สิ่งนี้เรียกว่า \"เทคนิคการผลิตขั้นสูง\" รวมถึงเทคนิคการบริหารเวลาแบบต่างๆ ที่นักวิชาการที่มีชื่อเสียงใช้กันทุกยุคทุกสมัย",
  ui_story_5037_50371401_39_dialog_content = "อย่างไรก็ตามแผนนี้จำเป็นต้องมีความรู้พื้นฐานของอุตสาหกรรมเพื่อให้เข้าใจเพียงพอในการใช้งาน",
  ui_story_5037_50371401_40_dialog_content = "ไปข้างหน้า PlayerName! เลือกแผนที่คุณคิดว่าเหมาะกับคุณที่สุด!",
  ui_story_5037_50371401_41_dialog_content = "แผนที่เหมาะกับฉันที่สุด...",
  ui_story_5037_50371401_42_dialog_content = "ฉันยังค่อนข้างขาดประสบการณ์ในฐานะโปรดิวเซอร์ ดังนั้นฉันคิดว่าคนนี้น่าจะทำได้—",
  ui_story_5037_50371401_43_option_content = "\"ผู้ผลิต: จากมือใหม่สู่ผู้เชี่ยวชาญ\"",
  ui_story_5037_50371401_44_dialog_content = "ถ้าฉันต้องการเริ่มต้นด้วยพื้นฐาน แผนนี้น่าจะเป็นทางเลือกที่ปลอดภัยที่สุดของฉัน!",
  ui_story_5037_50371401_45_dialog_content = "จริงด้วยสินะ",
  ui_story_5037_50371401_46_dialog_content = "ก็เป็นอันเรียบร้อย! ตั้งแต่วันนี้ คุณจะใช้สิ่งนี้เพื่อช่วยให้คุณเรียนรู้วิธีการเป็นผู้ผลิตมืออาชีพ!",
  ui_story_5037_50371401_47_dialog_content = "จะพยายามเต็มที่นะ!",
  ui_story_5037_50371401_48_dialog_content = "<color=#828282>ในเวลาต่อมา</color>",
  ui_story_5037_50371401_49_dialog_content = "ความรับผิดชอบหลักของโปรดิวเซอร์... ติดตามความคืบหน้า พัฒนาตาราง...",
  ui_story_5037_50371401_50_dialog_content = "อะไรอีก? เอ่อ ฉันคิดว่าฉันลืมไปแล้ว...",
  ui_story_5037_50371401_51_dialog_content = "จะไม่พักหน่อยเหรอ?",
  ui_story_5037_50371401_52_dialog_content = "คุณจำมามากแล้ว ขั้นตอนต่อไปของคุณคือพยายามนำแนวคิดเหล่านั้นไปปฏิบัติ",
  ui_story_5037_50371401_53_option_content = "“เทคนิคการผลิตขั้นสูง”",
  ui_story_5037_50371401_54_dialog_content = "ฉันตัดสินใจแล้วว่าจะท้าทายตัวเองด้วยการทำสิ่งนี้ ดังนั้นมาเริ่มด้วยสิ่งที่ยากกันเถอะ!",
  ui_story_5037_50371401_55_dialog_content = "คุณแน่ใจไหม?!",
  ui_story_5037_50371401_56_dialog_content = "หากคุณต้องการดำเนินการต่อ เราจะพยายามอย่างเต็มที่เพื่อสนับสนุนคุณ",
  ui_story_5037_50371401_57_dialog_content = "ฉันควรจะสบายดี!",
  ui_story_5037_50371401_58_dialog_content = "<color=#828282>ในเวลาต่อมา</color>",
  ui_story_5037_50371401_59_dialog_content = "มันเป็นเรื่องยากเกินไป!",
  ui_story_5037_50371401_60_dialog_content = "เห็นด้วยครับ มันดูยากไปหน่อย...",
  ui_story_5037_50371401_61_dialog_content = "ฉันรู้สึกเหมือนกันตอนที่กำลังวางแผนนี้... มีหัวข้อที่ซับซ้อนมากมายที่เกี่ยวข้อง ซึ่งทั้งหมดนี้เชื่อมโยงถึงกันไม่ทางใดก็ทางหนึ่ง",
  ui_story_5037_50371401_62_dialog_content = "ดูเหมือนว่าฉันจะต้องดำเนินการทีละขั้นตอนหากต้องการเรียนรู้สิ่งที่ถูกต้อง",
  ui_story_5037_50371401_63_dialog_content = "มันสายไปแล้ว วันนี้ขอหยุดแค่นี้ก่อน",
  ui_story_5037_50371401_64_dialog_content = "การทำงานที่ดี, PlayerName!",
  ui_story_5037_50371401_65_dialog_content = "ดีมาก",
  ui_story_5037_50371401_66_dialog_content = "ฉันควรจะเป็นคนพูดแบบนั้นสิ! ฉันแน่ใจว่ามันไม่ง่ายเลยที่จะรวบรวมวัตถุดิบเหล่านี้ทั้งหมด...",
  ui_story_5037_50371401_67_dialog_content = "เราเป็นเพื่อนที่ดีต่อกัน ไม่จำเป็นต้องมีพิธีรีตอง",
  ui_story_5037_50371401_68_dialog_content = "กลับไปพักผ่อนบ้าง โอเค?",
  ui_story_5037_50371401_69_dialog_content = "ใช่เหมือนกันกับคุณสองคน!",
  ui_story_5037_50371401_70_dialog_content = "เรายังมีเรื่องต้องจัดการก่อนกลับ ไม่ต้องรอเรา",
  ui_story_5037_50371401_71_dialog_content = "ฮะ? คุณกำลังจะไปไหน?",
  ui_story_5037_50371401_72_dialog_content = "เราทำการสัมภาษณ์นักร้อง Aurorian ในเมือง เราต้องการเรียนรู้เทคนิคการร้องเพลงจากพวกเขา",
  ui_story_5037_50371401_73_dialog_content = "แม้ว่าสไตล์และภูมิหลังจะแตกต่างกัน แต่ก็ยังต้องมีคำแนะนำที่จะนำเสนอ",
  ui_story_5037_50371401_74_dialog_content = "ถ้าเราสามารถระบุเทคนิคของพวกเขาและนำเสนอให้ Goldie ฉันแน่ใจว่ามันจะมีประโยชน์มากสำหรับเธอ",
  ui_story_5037_50371401_75_dialog_content = "แต่คุณได้ทำไปมากแล้วเพื่อช่วยฉัน!",
  ui_story_5037_50371401_76_dialog_content = "ฉันรู้สึกว่าถ้าใครต้องการพักผ่อน คุณสองคน...",
  ui_story_5037_50371401_77_dialog_content = "ไม่ต้องกังวลเกี่ยวกับเรา! ฉันยังรู้สึกกระปรี้กระเปร่าและพร้อมลุย!",
  ui_story_5037_50371401_78_dialog_content = "นี่เป็นประสบการณ์ใหม่และน่าตื่นเต้นสำหรับเราทั้งคู่",
  ui_story_5037_50371401_79_dialog_content = "อาจเป็นเพราะเหตุนี้ที่เราไม่รู้สึกเหนื่อยแม้งานทั้งหมดที่เราได้ทำ",
  ui_story_5037_50371401_80_dialog_content = "คุณไม่รู้สึกอย่างนั้นบ้างหรือบางครั้ง PlayerName?",
  ui_story_5037_50371401_81_dialog_content = "ฉันทำ ใช่...",
  ui_story_5037_50371401_82_dialog_content = "นับตั้งแต่ฉันเริ่มทำงานเป็นโปรดิวเซอร์ ฉันไม่คิดว่าวันหนึ่งผ่านไปแล้วที่ฉันไม่ได้ทำงานตั้งแต่เช้าจรดค่ำ",
  ui_story_5037_50371401_83_dialog_content = "แต่เพราะความท้าทายใหม่ ๆ ที่ฉันเผชิญทุกวัน ฉันไม่รู้สึกเหนื่อยเท่าที่ควร!",
  ui_story_5037_50371401_84_dialog_content = "มันให้ความรู้สึกเหมือนตอนที่ฉันออกมาจากใต้ดินแล้วเจอพวกคุณ",
  ui_story_5037_50371401_85_dialog_content = "แม้ว่า Eclipsites จะไล่ตามเรามาหลายวัน แต่ฉันก็ไม่เคยรู้สึกเหนื่อยหรือสิ้นหวังเลย",
  ui_story_5037_50371401_86_dialog_content = "นั่นคือความตื่นเต้นที่การผจญภัยครั้งใหม่จะมอบให้!",
  ui_story_5037_50371401_87_dialog_content = "ใช่แล้ว!",
  ui_story_5037_50371401_88_dialog_content = "แต่ถึงอย่างนั้น ฉันก็ไม่สามารถยืนเฉยได้ในขณะที่คุณสองคนยุ่งมาก!",
  ui_story_5037_50371401_89_dialog_content = "หา?",
  ui_story_5037_50371401_90_dialog_content = "ทำไมกันนะ",
  ui_story_5037_50371401_91_dialog_content = "เพราะเราทุกคนอยู่ด้วยกัน มันจึงเป็นเช่นนี้เสมอมา",
  ui_story_5037_50371401_92_dialog_content = "ไม่ว่าการเดินทางจะยาวนานหรือการผจญภัยที่อันตรายแค่ไหน เราสามคนก็ยังอยู่ด้วยกันเสมอ",
  ui_story_5037_50371401_93_dialog_content = "นั่นเป็นเหตุผลที่ฉันมากับคุณ!",
  ui_story_5037_50371401_94_dialog_content = "แต่—",
  ui_story_5037_50371401_95_dialog_content = "ไม่ต้องห่วงฉัน! เราทุกคนจะทำให้ดีที่สุดเหมือนเช่นเคย",
  ui_story_5037_50371401_96_dialog_content = "แน่นอน! เหมือนที่เราเคยทำ!",
  ui_story_5037_50371501_1_dialog_content = "การประชุมในนาทีสุดท้ายของ Team PlayerName! สาม สอง หนึ่ง... ปฏิบัติการ!",
  ui_story_5037_50371501_2_dialog_content = "ขอโทษทีมาช้าไปหน่อย!",
  ui_story_5037_50371501_3_dialog_content = "ใช้ได้. อย่างน้อยคุณก็ทำได้!",
  ui_story_5037_50371501_4_dialog_content = "ฮะ? โกลดี้อยู่ไหน?",
  ui_story_5037_50371501_5_dialog_content = "เธอไปคุยกับ Lady Sheol เกี่ยวกับแผนการที่จะเกิดขึ้น ดังนั้นเธอจะไม่กลับมาพักหนึ่ง",
