  ui_story_5037_50371501_7_dialog_content = "ทำไมกันนะ",
  ui_story_5037_50371501_8_dialog_content = "เราอยากแสดงความยินดีกับคุณทั้งคู่สำหรับการจัดคอนเสิร์ตเปิดตัวที่ประสบความสำเร็จ",
  ui_story_5037_50371501_9_dialog_content = "เราได้เตรียมเครื่องดื่มและขนมไว้เมื่อคุณกับโกลดี้กลับมา",
  ui_story_5037_50371501_10_dialog_content = "ว้าวขอบคุณ! และไม่ต้องกังวล ฉันจะนำบางส่วนกลับมาให้โกลดี้อย่างแน่นอน",
  ui_story_5037_50371501_11_dialog_content = "ฉันแค่หวังว่าเธอจะอยู่ที่นี่เพื่อสนุกกับมันในตอนนี้...",
  ui_story_5037_50371501_12_dialog_content = "ฉันใช้เวลามากในการอบคุกกี้เหล่านี้ ดังนั้นฉันจึงอยากให้ทุกคนลองทำดูในขณะที่ยังใหม่ๆ",
  ui_story_5037_50371501_13_dialog_content = "ต้องใช้ความพยายามอย่างมากในการหาวิธีอบโดยไม่ให้ไหม้เช่นกัน",
  ui_story_5037_50371501_14_dialog_content = "ดูเหมือนว่าคุณจะเทใจให้กับสิ่งเหล่านี้จริงๆ Vice...",
  ui_story_5037_50371501_15_dialog_content = "(คุกกี้เหล่านี้น่าจะรสชาติดีถ้าเธอพยายามอย่างหนักกับมัน... ใช่ไหม?)",
  ui_story_5037_50371501_16_dialog_content = "เวลาบินไปใช่ไหม ฉันไม่อยากจะเชื่อเลยว่าคอนเสิร์ตเปิดตัวได้จบลงไปแล้ว",
  ui_story_5037_50371501_17_dialog_content = "ช่าย... เราเคยจัดเวิร์คช็อปของ Producer's Crash Course มาแล้วหลายครั้งเช่นกัน!",
  ui_story_5037_50371501_18_dialog_content = "เมื่อเราเริ่มช่วยเหลือ PlayerName มาเป็นโปรดิวเซอร์ พวกเรายุ่งมาก...",
  ui_story_5037_50371501_19_dialog_content = "แต่ความพยายามทั้งหมดของเราเริ่มที่จะได้ผล! PlayerName สามารถช่วย Goldie จัดคอนเสิร์ตเปิดตัวสุดอลังการได้!",
  ui_story_5037_50371501_20_dialog_content = "เขากลายเป็นโปรดิวเซอร์ที่วางใจได้เลยทีเดียว",
  ui_story_5037_50371501_21_dialog_content = "ไม่ได้ล้อเล่น! คุณได้แสดงให้เห็นถึงความก้าวหน้าอย่างมาก!",
  ui_story_5037_50371501_22_dialog_content = "ฮิฮิฮิ... เจ้าสองคนกำลังจะทำให้ข้าหน้าแดง! ฉันคือคนที่ควรจะขอบคุณคุณ!",
  ui_story_5037_50371501_23_dialog_content = "ยินดีด้วย!",
  ui_story_5037_50371501_24_dialog_content = "ยินดีด้วย PlayerName!",
  ui_story_5037_50371501_25_dialog_content = "ขอบคุณครับ!",
  ui_story_5037_50371501_26_dialog_content = "เอาล่ะ มาเริ่มปาร์ตี้กันเลย!",
  ui_story_5037_50371501_27_dialog_content = "นานไปชาจะเย็น!",
  ui_story_5037_50371501_28_dialog_content = "<color=#828282>ซวบ ซวบ...</color>",
  ui_story_5037_50371501_29_dialog_content = "... เมื่อกี้พวกเจ้าได้ยินเสียงแปลกๆ ไหม?",
