  ui_story_5037_50371501_31_dialog_content = "<color=#828282>เสียงกรอบแกรบ เสียงกรอบแกรบ——</color>",
  ui_story_5037_50371501_32_dialog_content = "นั่นมันอีกแล้ว เหมือนดังมาจากเครื่องดนตรีใกล้ตัว",
  ui_story_5037_50371501_33_dialog_content = "อาจเป็นเพียงลม?",
  ui_story_5037_50371501_34_dialog_content = "<color=#828282>เสียงกรอบแกรบ เสียงกรอบแกรบ——</color>",
  ui_story_5037_50371501_35_dialog_content = "...",
  ui_story_5037_50371501_36_dialog_content = "ฉันคิดว่ามีบางอย่างซ่อนอยู่หลังกลอง...",
  ui_story_5037_50371501_37_dialog_content = "อาจจะเป็น... Eclipsite?",
