  ui_story_5037_50371501_44_dialog_content = "โล โล! (แปล: แต่ฉันไม่คิดว่าจะพบคนมากมายที่นี่พร้อมกัน!)",
  ui_story_5037_50371501_45_dialog_content = "โล... โล! (แปล: ดูเหมือนว่าปกของฉันจะปลิว... ฉันต้องหาทางออกจากที่นี่ เร็วเข้า!)",
