  ui_story_5037_50371601_64_dialog_content = "ทำงานเดิมๆ ซ้ำๆ วันแล้ววันเล่า... ฉันคุ้นเคยกับงานนั้นดี แต่ก็อดไม่ได้ที่จะรู้สึกเบื่อบ้างในบางครั้ง...",
  ui_story_5037_50371601_65_dialog_content = "ฉันรู้ว่าคุณรู้สึกอย่างไร...",
  ui_story_5037_50371601_66_dialog_content = "แม้แต่สิ่งที่น่าตื่นเต้นที่สุดก็กลายเป็นเรื่องน่าเบื่อไปชั่วขณะ",
  ui_story_5037_50371601_67_dialog_content = "ด้วยเหตุนี้เราจึงต้องหาวิธีใหม่ ๆ เพื่อท้าทายตัวเองอยู่เสมอ",
  ui_story_5037_50371601_68_dialog_content = "ถึงกระนั้น นี่เป็นประสบการณ์อันล้ำค่า!",
  ui_story_5037_50371601_69_dialog_content = "ฉันต้องช่วยโกลดี้จัดคอนเสิร์ต และฉันต้องเรียนไปพร้อมกับคุณทั้งคู่",
  ui_story_5037_50371601_70_dialog_content = "ฉันไม่สามารถขอวิธีที่ดีกว่าในการเรียนรู้และเติบโตเป็นคน!",
  ui_story_5037_50371601_71_dialog_content = "คุณอาจสร้างชื่อให้ตัวเองได้ถ้าคุณอยู่ที่นี่และเป็นโปรดิวเซอร์ต่อไป",
  ui_story_5037_50371601_72_dialog_content = "คุณชอบแบบไหนมากกว่ากัน? เป็นผู้ผลิตหรือเป็นนักผจญภัย?",
  ui_story_5037_50371601_73_dialog_content = "คุณกำลังล้อเล่นฉัน? คำตอบของฉันควรจะชัดเจนในวันนี้!",
  ui_story_5037_50371601_74_dialog_content = "!",
  ui_story_5037_50371601_75_dialog_content = "การผจญภัยกับพวกคุณคือสิ่งที่ทำให้ฉันมีความสุขที่สุด!",
  ui_story_5037_50371701_1_dialog_content = "ฟลอรีน? ฉันไม่ได้คาดหวังให้คุณมาที่นี่! ยินดีต้อนรับ ยินดีต้อนรับ!",
  ui_story_5037_50371701_2_dialog_content = "ถ้าคุณมาฟังโกลดี้ร้องเพลง ฉันเกรงว่าจะต้องทำให้คุณผิดหวัง คอนเสิร์ตไม่ได้จัดอีกไม่กี่วัน และเธอยังอยู่ระหว่างการฝึกซ้อม",
  ui_story_5037_50371701_3_dialog_content = "ฉันไม่ได้มาที่นี่เพื่อเข้าร่วมคอนเสิร์ต",
  ui_story_5037_50371701_4_dialog_content = "หา?",
  ui_story_5037_50371701_5_dialog_content = "ฉันมาที่นี่เพื่อให้ความช่วยเหลือ",
  ui_story_5037_50371701_6_dialog_content = "ฉันได้ยินมาว่าคุณกำลังลองทำอาชีพใหม่? ผู้ผลิต ฉันเชื่อว่าพวกเขาเรียกมันว่า",
  ui_story_5037_50371701_7_dialog_content = "ฉันมาเป็นเพื่อนคุณเพื่อดูว่าคุณเป็นอย่างไรบ้าง",
  ui_story_5037_50371701_8_dialog_content = "บอกฉันที Caelestite คนสุดท้าย... มีอะไรให้ฉันช่วยไหม?",
  ui_story_5037_50371701_9_dialog_content = "คิดว่าไม่นะ...",
  ui_story_5037_50371701_10_dialog_content = "งั้นรึ...",
  ui_story_5037_50371701_11_dialog_content = "(ห๊ะ ทำไมฟลอรีนดูผิดหวังจัง?)",
  ui_story_5037_50371701_12_dialog_content = "(เป็นเพราะฉันไม่ต้องการความช่วยเหลือจากเธอในตอนนี้...?)",
  ui_story_5037_50371701_13_dialog_content = "ว-เดี๋ยวก่อน! มีบางอย่างที่ฉันสามารถใช้มือได้!",
  ui_story_5037_50371701_14_dialog_content = "ว่าไง",
