  ui_story_5037_50371701_16_dialog_content = "(ฉันไม่อยากทำให้เธอผิดหวัง แต่ฉันก็ไม่อยากรบกวนเธอเช่นกัน...)",
  ui_story_5037_50371701_17_dialog_content = "(เดี๋ยวนะ เธอบอกว่าเธอเคยเป็นประธานนักเรียนไม่ใช่เหรอ ในกรณีนั้น...)",
