  ui_story_5037_50371701_19_dialog_content = "โกลดีกำลังเขียนเพลงใหม่ แต่ยังขาดเพลงประกอบ บางทีคุณอาจช่วยเธอได้",
  ui_story_5037_50371701_20_dialog_content = "ดนตรีประกอบ? ขออภัย ฉันไม่ค่อยคุ้นเคยกับหัวข้อ...",
