  ui_story_5037_50371701_22_dialog_content = "ดีมาก ขอบคุณมาก!",
  ui_story_5037_50371701_23_option_content = "ขอความช่วยเหลือเรื่องเรียน",
  ui_story_5037_50371701_24_dialog_content = "โกลดีต้องการให้ฉันวิจารณ์การแสดงของเธออย่างสร้างสรรค์ แต่ฉันไม่เข้าใจจริงๆ ว่าเธอกำลังมองหาอะไรอยู่",
  ui_story_5037_50371701_25_dialog_content = "ฉันต้องเรียนรู้เกี่ยวกับดนตรีให้ได้มากที่สุดโดยเร็วที่สุด เพื่อที่ฉันจะได้ให้ข้อเสนอแนะที่เธอต้องการ ข้อเสนอแนะใด ๆ",
  ui_story_5037_50371701_26_dialog_content = "คุณมาถูกคนแล้ว! ฉันรู้ทุกสิ่งที่ควรรู้เกี่ยวกับการศึกษาด้วยตนเองอย่างเป็นระบบ และฉันเต็มใจอย่างยิ่งที่จะแบ่งปันความรู้กับคุณ!",
