  ui_story_5037_50371701_28_dialog_content = "<color=#828282>ในเวลาต่อมา</color>",
  ui_story_5037_50371701_29_dialog_content = "... ที่นั่น! ฉันได้แบ่งปันทุกสิ่งที่ฉันรู้กับคุณ",
