  ui_story_5037_50371701_40_dialog_content = "พวกเขาไม่...?",
  ui_story_5037_50371701_41_dialog_content = "พวกเขาเป็นสุดยอดของประสบการณ์ของตัวเองในฐานะนักเรียนเช่นกัน",
  ui_story_5037_50371701_42_dialog_content = "การทำงานหนักและการอุทิศตนเป็นวิธีที่คนธรรมดาสามารถทำสิ่งพิเศษให้สำเร็จได้... ดังนั้นอย่าประเมินคุณค่าของการทำงานหนักต่ำเกินไป",
