  ui_story_5037_50371701_44_dialog_content = "ยังไงก็ตาม ทำไมคุณยังใส่ของเก่าๆ พวกนั้นอยู่ล่ะ? คุณไม่ต้องการเปลี่ยนหรือไม่",
