  ui_story_5037_50371901_14_dialog_content = "มีความแตกต่างบางอย่าง นอกจากการร้องเพลงแล้ว ฉันยังต้องเรียนรู้ทักษะอื่นๆ ด้วย เช่น การเต้นและการแสดง!",
  ui_story_5037_50371901_15_dialog_content = "ฉันเห็น. และนั่นเป็นเหตุผลว่าทำไมคุณถึงอยากเรียนการเต้นคางุระ?",
