  ui_story_5037_50371901_37_dialog_content = "นี่เป็นครั้งแรกที่ฉันได้เต้นคางุระ ดังนั้นฉันจึงกังวลว่าจะทำให้ถูกต้องหรือไม่",
  ui_story_5037_50371901_38_dialog_content = "อ่า... บางทีนั่นอาจเป็นที่มาของปัญหา",
  ui_story_5037_50371901_39_dialog_content = "คางุระเป็นการร่ายรำเพื่อเทพเจ้า เมื่อคุณเคลื่อนไหว ความคิดของคุณต้องอยู่กับพระเจ้าเท่านั้น",
  ui_story_5037_50371901_40_dialog_content = "จากนั้นหัวใจของคุณจะแสดงออกผ่านการเต้น",
  ui_story_5037_50371901_41_dialog_content = "โอ้...! เอาล่ะ ฉันคิดว่าฉันเข้าใจแล้ว!",
  ui_story_5037_50371901_42_dialog_content = "เร็วจัง!",
  ui_story_5037_50371901_43_dialog_content = "มันค่อนข้างคล้ายกับที่ฉันมักจะแสดง!",
  ui_story_5037_50371901_44_dialog_content = "แฟนๆ ของฉันเป็นสิ่งเดียวที่ฉันคิดถึงเมื่อฉันร้องเพลงหรือเต้นรำ และฉันหวังว่าฉันจะทำให้พวกเขามีความสุขมากแค่ไหน",
  ui_story_5037_50371901_45_dialog_content = "เมื่อฉันอยู่ในโซนนั้น เสียงร้องและการเคลื่อนไหวของฉันดูเหมือนจะลื่นไหลแทบไม่ต้องพยายาม",
  ui_story_5037_50371901_46_dialog_content = "การเต้นรำอาจแตกต่างกัน แต่มีบางอย่างเหมือนกัน",
  ui_story_5037_50371901_47_dialog_content = "คุณจะลองเต้นอีกครั้งโดยคำนึงถึงสิ่งนั้นหรือไม่?",
  ui_story_5037_50371901_48_dialog_content = "ได้เลยค่ะ",
  ui_story_5037_50371901_49_dialog_content = "คิดถึงแต่แฟน...",
  ui_story_5037_50371901_50_dialog_content = "(น่าทึ่งมาก! เป็นความรู้สึกที่แตกต่างอย่างสิ้นเชิงเมื่อเทียบกับครั้งแรก!)",
  ui_story_5037_50371901_51_dialog_content = "(แต่ดูเหมือนว่ายังมีความแตกต่างอยู่บ้างระหว่างการเต้นรำของโกลดีกับของรินน์)",
  ui_story_5037_50371901_52_dialog_content = "คิดอะไรอยู่รินเนะ? PlayerName?",
  ui_story_5037_50371901_53_option_content = "มันเหมือนของ Rinne มาก!",
  ui_story_5037_50371901_54_dialog_content = "จริงเหรอ เยี่ยมเลย!",
  ui_story_5037_50371901_55_dialog_content = "อืม... ยังมีความแตกต่างอยู่บ้าง",
  ui_story_5037_50371901_56_dialog_content = "งั้นเหรอ",
  ui_story_5037_50371901_57_option_content = "การเต้นในแบบของคุณมีเสน่ห์ในตัวเอง!",
  ui_story_5037_50371901_58_dialog_content = "งั้นเหรอ",
  ui_story_5037_50371901_59_dialog_content = "การเต้นของคุณรู้สึกมีชีวิตชีวาขึ้นเล็กน้อย เบาลงเล็กน้อย",
  ui_story_5037_50371901_60_dialog_content = "โกลดี้กับฉันกำลังเต้นรำเพื่อผู้คนที่แตกต่างกัน",
  ui_story_5037_50371901_61_dialog_content = "การเต้นรำของโกลดีมีไว้สำหรับผู้ชมที่กระตือรือร้นและหลงใหล",
  ui_story_5037_50371901_62_dialog_content = "การเคลื่อนไหวที่เหมือนกันสามารถถ่ายทอดอารมณ์ที่แตกต่างกันไปตามแต่ละบุคคล",
  ui_story_5037_50371901_63_dialog_content = "นี่ไม่ใช่สิ่งเลวร้ายและเป็นธรรมชาติโดยสิ้นเชิง ดังนั้นจึงไม่จำเป็นต้องกังวลเกี่ยวกับเรื่องนี้",
  ui_story_5037_50371901_64_dialog_content = "ความคิดและการเคลื่อนไหวของคุณเป็นของคุณคนเดียว",
  ui_story_5037_50371901_65_dialog_content = "ได้เลยค่ะ!",
  ui_story_5037_50371901_66_dialog_content = "ขอบคุณสำหรับคำแนะนำของคุณ!",
  ui_story_5037_50372001_1_dialog_content = "เนื่องจากวันนี้เราอยู่ที่อื่น ฉันจึงต้องเริ่มถ่ายทำ ดูการแสดงออกของคุณพวก",
  ui_story_5037_50372001_2_dialog_content = "3... 2... 1... ปฏิบัติการ!",
  ui_story_5037_50372001_3_dialog_content = "เรากำลังกลิ้ง? *ไอ*...",
  ui_story_5037_50372001_4_dialog_content = "ชั้นเรียนเสียงของฉันเริ่มต้นขึ้นแล้ว",
  ui_story_5037_50372001_5_dialog_content = "สวัสดี นีน่า!",
  ui_story_5037_50372001_6_dialog_content = "ผมรู้สึกสับสนนิดหน่อย...",
  ui_story_5037_50372001_7_dialog_content = "เราควรจะฝึกเสียงตอนนี้ไม่ใช่เหรอ? เรากำลังทำอะไรที่คอนเสิร์ตฮอลล์?",
  ui_story_5037_50372001_8_dialog_content = "คำถามที่ยอดเยี่ยม PlayerName.",
  ui_story_5037_50372001_9_dialog_content = "บทเรียนนี้จะไม่ทำงานแต่เป็นแบบพาสซีฟ วันนี้เรามาฟัง",
  ui_story_5037_50372001_10_dialog_content = "การฟัง...?",
  ui_story_5037_50372001_11_dialog_content = "การฟังเพลงของศิลปินคนอื่นเป็นส่วนสำคัญของการฝึกฝนของไอดอล!",
  ui_story_5037_50372001_12_dialog_content = "เราต้องรู้ว่าแฟน ๆ ชอบอะไรในปัจจุบันถ้าเราต้องการทำเพลงที่คนอยากฟัง",
  ui_story_5037_50372001_13_dialog_content = "ใช่! รู้เทรนด์ ตามเทรนด์ และนำเทรนด์ นี่คือสัดส่วนหลักของอุตสาหกรรม!",
  ui_story_5037_50372001_14_dialog_content = "วันนี้เราจะไปฟังเพลงที่ชื่อว่า \"Phantom of the Theatre\"",
  ui_story_5037_50372001_15_dialog_content = "เป็นการบอกเล่าเรื่องราวของนักแสดงละครเวทีอมตะ",
  ui_story_5037_50372001_16_dialog_content = "การเล่นที่เปลี่ยนไปทำให้เส้นทางที่เชื่อมโยงแต่ละยุคของ Umbraton",
  ui_story_5037_50372001_17_dialog_content = "ที่น่าตื่นตาตื่นใจ!",
  ui_story_5037_50372001_18_dialog_content = "วัฒนธรรมป๊อปเป็นภาพสะท้อนของจิตวิญญาณ ท้ายที่สุด!",
  ui_story_5037_50372001_19_dialog_content = "ยอดเยี่ยม สิบคะแนนสำหรับโกลดี้",
  ui_story_5037_50372001_20_dialog_content = "โปรดส่งเอกสารนี้ด้วย Minos",
  ui_story_5037_50372001_21_dialog_content = "ค่ะคุณหญิง",
  ui_story_5037_50372001_22_dialog_content = "นี่อะไร...?",
  ui_story_5037_50372001_23_dialog_content = "มิสปรุงเองโดยเฉพาะ แสดงรายการเพลงและโอเปร่ายอดนิยมทั้งหมดของ Umbraton ในช่วงทศวรรษที่ผ่านมา",
  ui_story_5037_50372001_24_dialog_content = "อย่าลืมดูแลมัน",
  ui_story_5037_50372001_25_dialog_content = "ค-ครับ...",
  ui_story_5037_50372001_26_dialog_content = "ในชั้นเรียนนี้ คุณจะได้เรียนรู้เกี่ยวกับแต่ละเพลงเหล่านี้ รวมถึงแนวโน้มของ Umbraton ในช่วงสิบปีที่ผ่านมา",
  ui_story_5037_50372001_27_dialog_content = "สิ่งนี้จะช่วยปรับแต่งรสนิยมของคุณ และช่วยให้คุณบันทึกเพลงที่กำลังเป็นที่นิยมได้มากขึ้น",
  ui_story_5037_50372001_28_dialog_content = "นีน่า ฉันซาบซึ้งในความพยายามของคุณ แต่...",
  ui_story_5037_50372001_29_dialog_content = "นี่มันเกินไปหรือเปล่าเนี่ย?!",
  ui_story_5037_50372001_30_dialog_content = "คุณไม่สามารถคาดหวังให้เราอ่านทั้งหมดในวันนี้?",
  ui_story_5037_50372001_31_dialog_content = "อ่านพวกเขาทั้งหมด? ไม่ ไม่แน่นอน! ฉันไม่เคยกำหนดงานที่เป็นไปไม่ได้ แทบจะไม่สมเหตุสมผลเลย",
  ui_story_5037_50372001_32_dialog_content = "แต่ละเพลงเหล่านี้จะถูกอ้างอิงในสิ่งที่เรากำลังรับชมในวันนี้",
  ui_story_5037_50372001_33_dialog_content = "คุณสามารถดูรายการทั้งหมดที่ฉันรวบรวมไว้ เพื่อทำความเข้าใจอย่างลึกซึ้งยิ่งขึ้นว่าวัฒนธรรมป๊อปแตกต่างกันอย่างไรในแต่ละยุค",
  ui_story_5037_50372001_34_dialog_content = "ขอบคุณมาก!",
  ui_story_5037_50372001_35_dialog_content = "เราจะศึกษาอย่างใกล้ชิด!",
  ui_story_5037_50372001_36_dialog_content = "การแสดงกำลังจะเริ่มขึ้นแล้ว ดังนั้นเราควรรีบเข้าไปนั่ง",
  ui_story_5037_50372001_37_dialog_content = "ตามนี้นะทุกคน",
  ui_story_5037_50372001_38_dialog_content = "มิสกรุณาจัดหาที่นั่งวีไอพีให้กับคุณ",
  ui_story_5037_50372001_39_dialog_content = "ว้าว ใกล้เวทีแล้ว! เราน่าจะมีมุมมองที่ดีที่สุดของการแสดงทั้งหมด!",
  ui_story_5037_50372001_40_dialog_content = "<color=#828282>...</color>",
  ui_story_5037_50372001_41_dialog_content = "\"ช่วงเวลาแห่งความสุข เสียงเพลงอันไพเราะ...",
  ui_story_5037_50372001_42_dialog_content = "“สาวสวย คุณช่วยเต้นรำเพื่อเป็นเกียรติแก่ฉันได้ไหม”",
  ui_story_5037_50372001_43_dialog_content = "นี่คือ \"Kleo and Jessica\" หนึ่งในละครที่เก่าแก่ที่สุดของ Umbraton",
  ui_story_5037_50372001_44_dialog_content = "ฉันรู้สิ่งนี้! เคยได้ยินนิทานตอนเด็กดัดแปลงมาจากละคร!",
  ui_story_5037_50372001_45_dialog_content = "บอกเล่าเรื่องราวอันน่าสลดใจของชาว Aurorian สองคนจากครอบครัวคู่แข่งที่ตกหลุมรักกัน",
  ui_story_5037_50372001_46_dialog_content = "ถูกตัอง. อย่างที่คุณเห็น ในช่วงเวลานี้ วัฒนธรรม Umbraton ได้รับอิทธิพลอย่างมากจาก Lumopolis",
  ui_story_5037_50372001_47_dialog_content = "เราสามารถเรียนรู้มากมายเกี่ยวกับชีวิตและนิสัยของ Lumo Nobles ร่วมสมัยได้จากสิ่งนี้ เช่น...",
  ui_story_5037_50372001_48_dialog_content = "(นีน่าและโกลดี้กำลังเริ่มขึ้นจริงๆ)",
  ui_story_5037_50372001_49_dialog_content = "(ละครไม่เป็นไร แต่ฉันไม่ค่อยรู้เรื่องประวัติศาสตร์ของ Lumopolis หรือ Umbraton มากนัก...)",
  ui_story_5037_50372001_50_dialog_content = "(ฉันง่วง... ฉันช่วยไม่ได้ การดูสิ่งที่ฉันไม่เข้าใจจริงๆทำให้ฉันหาว...)",
  ui_story_5037_50372001_51_dialog_content = "(แต่นีน่าไปจัดการเรื่องพวกนี้ซะเยอะ...)",
  ui_story_5037_50372001_52_option_content = "อย่าปล่อยให้ความเหนื่อยล้า",
  ui_story_5037_50372001_53_dialog_content = "(ไม่ ฉันนอนไม่หลับ ฉันต้องดูเรื่องนี้ให้จบ!)",
  ui_story_5037_50372001_54_dialog_content = "(นี่คือเอกสารอ้างอิงอันล้ำค่า!)",
  ui_story_5037_50372001_55_dialog_content = "<color=#828282>หลังจากอุตสาหะตื่นขึ้นจนจบการแสดง</color>",
  ui_story_5037_50372001_56_dialog_content = "ฉันไม่รู้เลยว่าการพัฒนาทางวัฒนธรรมของ Umbraton ซับซ้อนแค่ไหนจนกระทั่งตอนนี้!",
  ui_story_5037_50372001_57_dialog_content = "ฉันได้เรียนรู้มากเช่นกัน!",
  ui_story_5037_50372001_58_dialog_content = "ทั้งที่ไม่ค่อยรู้เรื่องเนื้อหา...",
  ui_story_5037_50372001_59_dialog_content = "ไม่ต้องกังวล! ฉันได้เน้นจุดที่เกี่ยวข้องในเนื้อหาแล้ว",
  ui_story_5037_50372001_60_dialog_content = "คุณสามารถพลิกดูเพื่อรีเฟรชความทรงจำได้ทุกเมื่อที่คุณต้องการ",
  ui_story_5037_50372001_61_dialog_content = "ว้าว ขอบคุณอีกครั้งที่สละเวลาทำสิ่งนี้ให้เรา นีน่า!",
  ui_story_5037_50372001_62_option_content = "ยอมหลับใหล.",
  ui_story_5037_50372001_63_dialog_content = "(ต้องตื่น...ต้องอยู่...Zzzz...)",
  ui_story_5037_50372001_64_dialog_content = "<color=#828282>ใครจะรู้ว่าอีกนานแค่ไหน...</color>",
  ui_story_5037_50372001_65_dialog_content = "PlayerName? PlayerName!",
  ui_story_5037_50372001_66_dialog_content = "ขอฉันลองหน่อย มิสโกลดี้",
  ui_story_5037_50372001_67_dialog_content = "ช่วยปลุกหน่อยได้ไหม PlayerName!",
  ui_story_5037_50372001_68_dialog_content = "เอ๋?!",
  ui_story_5037_50372001_69_dialog_content = "ทำไมคุณถึงนอนหลับ? การแสดงจบลงแล้ว",
  ui_story_5037_50372001_70_dialog_content = "อะไร มันจบแล้ว?!",
  ui_story_5037_50372001_71_dialog_content = "ฉันหมกมุ่นอยู่กับการอธิบายเรื่องให้โกลดี้ฟังมากเกินไป จนฉันไม่ทันสังเกตว่าคุณหลับไปแล้ว...",
  ui_story_5037_50372001_72_dialog_content = "น่ารังเกียจชะมัดที่ปฏิเสธน้ำใจของนาง...",
  ui_story_5037_50372001_73_dialog_content = "ข-ขอโทษค่ะ",
  ui_story_5037_50372001_74_dialog_content = "มันเป็นความผิดพลาดของฉัน...",
  ui_story_5037_50372001_75_dialog_content = "ไม่เป็นไรหรอก",
  ui_story_5037_50372001_76_dialog_content = "น่าเสียดายที่คุณพลาดโอกาสที่จะเพิ่มพูนความรู้ในขณะที่เพลิดเพลินกับการแสดง",
  ui_story_5037_50372001_77_dialog_content = "แต่โชคดีสำหรับคุณ ฉันได้เน้นจุดที่เกี่ยวข้องในเนื้อหาแล้ว",
  ui_story_5037_50372001_78_dialog_content = "คุณจะเลือกบางอย่างหากคุณตรวจทานจริง",
  ui_story_5037_50372001_79_dialog_content = "ฉันจะอ่านทั้งหมดอย่างระมัดระวัง! และไม่ยอมหลับยอมนอน!",
  ui_story_5037_50372001_80_dialog_content = "ฉันหวังว่าพวกคุณทุกคนจะได้อะไรจากการแสดงนี้",
  ui_story_5037_50372001_81_dialog_content = "การรู้ว่าประชาชนต้องการอะไรคือกุญแจสู่วัฒนธรรมสมัยนิยม คุณไม่สามารถฝังหัวของคุณในทรายและเพิกเฉยได้",
  ui_story_5037_50372001_82_dialog_content = "นี่คือความช่วยเหลือทั้งหมดที่ฉันสามารถให้คุณได้ จากนี้ไปขึ้นอยู่กับคุณสองคนที่จะใช้ความพยายาม",
  ui_story_5037_50372001_83_dialog_content = "ขอบคุณ คุณนีน่า ไมนอส!",
  ui_story_5037_50372001_84_dialog_content = "ใช่ขอบคุณ!",
  ui_story_5037_50372101_1_dialog_content = "เฟลอร์ ขอบคุณสำหรับการให้คำปรึกษาแก่โกลดี้กับฉัน—",
  ui_story_5037_50372101_2_dialog_content = "จุ๊ๆ!",
  ui_story_5037_50372101_3_dialog_content = "เอ๊ะ? ยืนพิงประตูทำไม เฟลอร์",
  ui_story_5037_50372101_4_dialog_content = "โปรด, PlayerName, โกลดี้... ฉันต้องรบกวนคุณให้เงียบสักครู่...",
  ui_story_5037_50372101_5_dialog_content = "...",
  ui_story_5037_50372101_6_dialog_content = "...",
  ui_story_5037_50372101_7_dialog_content = "แป่ว... ดูเหมือนพวกนั้นจะไปแล้ว",
  ui_story_5037_50372101_8_dialog_content = "อย่าบอกนะว่าตัวเองมีปัญหาอีกแล้ว?",
  ui_story_5037_50372101_9_dialog_content = "อืม...",
  ui_story_5037_50372101_10_dialog_content = "ฉันหมายถึง ระหว่างทางมาที่นี่ ฉันทักทายคนสองสามคนที่ฉันเคยช่วยไว้ก่อนหน้านี้...",
  ui_story_5037_50372101_11_dialog_content = "สวัสดี",
  ui_story_5037_50372101_12_dialog_content = "ฮะ? ทำไมถ้าไม่ใช่เฟลอร์! ขอบคุณมากสำหรับความช่วยเหลือของคุณเมื่อวันก่อน!",
  ui_story_5037_50372101_13_dialog_content = "แต่หลังจากได้ยินชื่อของฉัน ผู้คนก็เข้ามามากขึ้นเรื่อย ๆ ...",
  ui_story_5037_50372101_14_dialog_content = "อะไร เฟลอร์อยู่ที่นี่? ฉันเป็นหนี้คุณเป็นครั้งสุดท้ายจริงๆ!",
  ui_story_5037_50372101_15_dialog_content = "เฟลอร์!! ฉันเป็นแฟนตัวยง!!!",
  ui_story_5037_50372101_16_dialog_content = "ฉันใช้เวลานานมากในการหลีกหนีจากกลุ่มแฟนๆ ที่น่ารัก ฉันต้องใช้เส้นทางที่ยาวไกลเพื่อให้แน่ใจว่าไม่มีใครติดตามฉัน ...",
  ui_story_5037_50372101_17_dialog_content = "บางครั้งก็เป็นเรื่องยุ่งยากในการเป็นที่นิยม...",
  ui_story_5037_50372101_18_dialog_content = "ฉันอิจฉามาก ฉันหวังว่าฉันจะเป็นที่นิยมเหมือนคุณ!",
  ui_story_5037_50372101_19_dialog_content = "มันทรมาณมากจริงๆ",
  ui_story_5037_50372101_20_dialog_content = "นั่นจะไม่รบกวนฉันเลย!",
  ui_story_5037_50372101_21_dialog_content = "มันวิเศษมากที่จะดึงดูดแฟนๆ ให้มาสนุกกับการเต้นและร้องเพลงของฉัน!",
  ui_story_5037_50372101_22_dialog_content = "ถ้านั่นคือสิ่งที่คุณต้องการ ฉันไม่คัดค้าน",
  ui_story_5037_50372101_23_dialog_content = "แค่ว่าฉันได้รับความนิยมก็ต้องขอบคุณรัฐธรรมนูญพิเศษของฉัน",
  ui_story_5037_50372101_24_dialog_content = "ไม่ใช่แค่สิ่งที่สอนได้...",
  ui_story_5037_50372101_25_dialog_content = "จริงเหรอ",
  ui_story_5037_50372101_26_dialog_content = "และด้วยความสัตย์จริง ฉันไม่รู้จริง ๆ ว่าวิธีใดได้รับความนิยมเช่นกัน",
  ui_story_5037_50372101_27_dialog_content = "ด้วยความแปลกประหลาดของฉัน ฉันใช้เวลาส่วนใหญ่ไปกับการศึกษาวิธีที่จะไม่เด่นหรือแม้แต่ไม่ชอบ",
  ui_story_5037_50372101_28_dialog_content = "ไม่อยากจะเชื่อเลย...",
  ui_story_5037_50372101_29_dialog_content = "แล้วเราควรทำอย่างไร?",
  ui_story_5037_50372101_30_dialog_content = "รู้แล้วล่ะน่า!",
  ui_story_5037_50372101_31_dialog_content = "คุณได้คิดอะไรมาบ้าง?",
  ui_story_5037_50372101_32_dialog_content = "ในเมื่อเฟลอร์คิดหนักและนานเกี่ยวกับวิธีที่จะไม่เป็นที่นิยม ทำไมเราไม่ทำตรงข้ามไปเลย",
  ui_story_5037_50372101_33_dialog_content = "คุณหมายถึง ให้เฟลอร์สอนกลยุทธิ์แก่คุณ แล้วค่อยเปลี่ยนกลับงั้นเหรอ?",
  ui_story_5037_50372101_34_dialog_content = "เลยทำวิธีไม่นิยมให้เป็นนิยมแทน?",
  ui_story_5037_50372101_35_dialog_content = "ถูกต้อง! นี่คือเหตุผลที่คุณเป็นโปรดิวเซอร์ของฉัน คุณติดตามได้เร็วมาก!",
  ui_story_5037_50372101_36_dialog_content = "คุณคิดว่าจะได้ผลจริงหรือ?",
  ui_story_5037_50372101_37_dialog_content = "เราจะไม่มีทางรู้ถ้าไม่ลอง จริงไหม? คุณจะสอนฉันไหม เฟลอร์? โปรด?",
  ui_story_5037_50372101_38_dialog_content = "โอเค... พวกนายอยากเรียนรู้วิธีทำตัวไม่เด่นหรือไม่ชอบเอามากๆ ไหม?",
  ui_story_5037_50372101_39_dialog_content = "นายคิดว่าไง PlayerName?",
  ui_story_5037_50372101_40_dialog_content = "(ในเมื่อเราจะกลับกัน แน่นอนว่ายิ่งมีคนไม่ชอบคุณมากเท่าไหร่ พวกเขาจะยิ่งชอบคุณมากขึ้นเมื่อพลิกด้าน?)",
  ui_story_5037_50372101_41_option_content = "ทำอย่างไรให้ไม่เด่น",
  ui_story_5037_50372101_42_dialog_content = "การเป็นคนไม่เด่นนั้นค่อนข้างง่าย เคล็ดลับคือการเป็นเหมือนคนอื่น",
  ui_story_5037_50372101_43_dialog_content = "สิ่งที่คุณต้องทำคือทำตัวเหมือนคนอื่น ๆ ในขณะที่ปกปิดลักษณะเด่นที่ทำให้คุณโดดเด่น แค่นั้น!",
  ui_story_5037_50372101_44_dialog_content = "คุณทำให้มันฟังดูง่าย!",
  ui_story_5037_50372101_45_dialog_content = "โดยทั่วไปคุณจะไม่ดึงความสนใจมาที่ตัวเองหากคุณสวมเสื้อผ้าธรรมดาๆ น่าเบื่อและก้มหน้าก้มตาเดินไปรอบๆ",
  ui_story_5037_50372101_46_dialog_content = "บางคนสวมหมวกซึ่งช่วยอำพรางใบหน้าได้!",
  ui_story_5037_50372101_47_dialog_content = "ถ้าอย่างนั้นสิ่งที่ตรงกันข้ามก็คือ... เดินไปมาโดยยกศีรษะสูง อวดการร้องและเต้นของฉัน?",
  ui_story_5037_50372101_48_dialog_content = "ฟังดูแปลกๆ แต่เนื่องจากคุณร้องและเต้นได้ดีมาก...",
  ui_story_5037_50372101_49_dialog_content = "ก็น่าจะเพียงพอแล้วใช่ไหม?",
  ui_story_5037_50372101_50_option_content = "จะไม่ชอบได้อย่างไร",
  ui_story_5037_50372101_51_dialog_content = "เป็นเรื่องยากเล็กน้อยที่จะทำให้คนอื่นไม่ชอบคุณ",
  ui_story_5037_50372101_52_dialog_content = "ฉันได้ลองทำสิ่งต่างๆ มากมาย เช่น แอบดูอย่างมีพิรุธ แต่งตัวด้วยผ้าขี้ริ้ว หรือทำให้ใบหน้าสกปรก",
  ui_story_5037_50372101_53_dialog_content = "ฉันทำสำเร็จ แม้ว่าฉันจะถูกเข้าใจผิดว่าเป็นหัวขโมยถึงสองครั้ง...",
  ui_story_5037_50372101_54_dialog_content = "แต่เนื่องจากปัญหาเฉพาะของฉัน เมื่อผู้คนเห็นว่าฉันเป็นใครจริงๆ การใช้เล่ห์เหลี่ยมไม่ได้ผล",
