  ui_story_5037_50372101_56_dialog_content = "ตรงกันข้ามก็ต้องมีท่าทางที่ภูมิฐาน แต่งตัวดี และดูดี จริงไหม?",
  ui_story_5037_50372101_57_dialog_content = "และมองโลกในแง่ดีอยู่เสมอและยิ้มแบบไอดอลทุกที่ที่ฉันไป!",
  ui_story_5037_50372101_58_dialog_content = "ต้องทำงาน!",
  ui_story_5037_50372101_59_dialog_content = "อย่าลืมว่าแบริ่งของคุณเป็นปัจจัยสำคัญไม่ว่าคุณจะใช้วิธีใดก็ตาม",
  ui_story_5037_50372101_60_dialog_content = "คุณเป็นนักเต้นที่ยอดเยี่ยม โกลดี้ ดังนั้นคุณควรรู้เรื่องนี้อยู่แล้ว",
  ui_story_5037_50372101_61_dialog_content = "โดยสิ้นเชิง! การแบกรับและท่าทางเป็นสิ่งสำคัญเมื่อเต้น ความแตกต่างระหว่างการยืนตัวตรงกับการหลังค่อมเมื่อคุณเต้นนั้นแตกต่างกันมาก",
  ui_story_5037_50372101_62_dialog_content = "อย่างไรก็ตาม ขอบคุณมาก เฟลอร์!",
  ui_story_5037_50372101_63_dialog_content = "ด้วยความยินดี. หากมีอะไรที่เราสามารถช่วยได้ โปรดอย่าลังเลที่จะแจ้งให้เราทราบ",
  ui_story_5037_50372101_64_dialog_content = "ฉันพนันได้เลยว่าเหตุผลส่วนหนึ่งที่คุณโด่งดังมากก็คือคุณเต็มใจที่จะช่วยเหลือผู้คนอยู่เสมอ",
  ui_story_5037_50372101_65_dialog_content = "ย-คุณคิดว่า??",
  ui_story_5037_50372101_66_dialog_content = "แต่ฉันจะละเลยคนที่ต้องการความช่วยเหลือไม่ได้...",
  ui_story_5037_50372101_67_dialog_content = "และนั่นเป็นสิ่งที่ดี อย่าเปลี่ยนสิ่งนั้นเด็ดขาด!",
  ui_story_5037_50372101_68_dialog_content = "ได้เลย เข้าใจแล้ว",
  ui_story_5037_50372101_69_dialog_content = "ขอบคุณนะ PlayerName",
  ui_story_5037_50372101_70_dialog_content = "ผู้คนมักชอบช่วยเหลือผู้อื่นและทำความดี!",
  ui_story_5037_50372101_71_dialog_content = "PlayerNameเราควรไปลองสิ่งที่เราได้เรียนรู้!",
  ui_story_5037_50372101_72_dialog_content = "ตอนนี้?!",
  ui_story_5037_50372101_73_dialog_content = "เราควรตีเหล็กในขณะที่ยังร้อนอยู่! ไปกันเถอะ-",
