  ui_story_5037_50372101_75_dialog_content = "งั้นเหรอ",
  ui_story_5037_50372101_76_dialog_content = "<color=#828282>เอี๊ยด—</color>",
  ui_story_5037_50372101_77_dialog_content = "(มีคนมากมายอยู่ข้างนอก!)",
  ui_story_5037_50372101_78_dialog_content = "เฟลอร์อยู่ไหน?",
  ui_story_5037_50372101_79_dialog_content = "ฉันคิดว่าฉันเพิ่งได้ยินคนตะโกนชื่อเขา!",
