  ui_story_5037_50372101_81_dialog_content = "ขอให้ทุกคนใจเย็นๆ...",
  ui_story_5037_50372101_82_dialog_content = "พวกเรารักคุณ!!",
  ui_story_5037_50372101_83_dialog_content = "ว้าว! คุณดึงดูดพวกเขาจริงๆ!",
  ui_story_5037_50372101_84_dialog_content = "ความนิยมดูเหมือนจะเป็นเรื่องยุ่งยาก ...",
  ui_story_5037_50372201_1_dialog_content = "\"ข้างบนมันเหงา\"",
  ui_story_5037_50372201_2_dialog_content = "“กิน ดื่ม นอนคนเดียว...นี่แหละที่มาของศิลปะ”",
  ui_story_5037_50372201_3_dialog_content = "“รู้อย่างนี้แล้ว ก็จงรู้ไว้เถิดว่าความเหงาไม่ใช่ศัตรู แต่เป็นเพื่อน เป็นเพื่อนที่มั่นคง!”",
  ui_story_5037_50372201_4_dialog_content = "ยอดเลย!",
  ui_story_5037_50372201_5_dialog_content = "นั่นไม่ใช่บรรทัดจาก \"สัมภาษณ์คนดัง\" เหรอ?",
  ui_story_5037_50372201_6_dialog_content = "ขอบคุณหญิงสาว การที่คุณชอบการแสดงของฉันบ่งบอกรสนิยมทางศิลปะของคุณได้",
  ui_story_5037_50372201_7_dialog_content = "รอก่อน ชารอน คุณช่วยอธิบายอะไรหน่อยได้ไหม...?",
  ui_story_5037_50372201_8_dialog_content = "ชุด Eraveil ทั้งหมดปรากฏขึ้นที่นี่ในเวลาเพียงสิบนาทีที่เราจากไปได้อย่างไร",
  ui_story_5037_50372201_9_dialog_content = "คุณไม่ควรแปลกใจเลยเพื่อนของฉัน วิศวกรของ Illumina เก่งที่สุดใน Astra",
  ui_story_5037_50372201_10_dialog_content = "ฉันไม่คิดว่านี่คือสิ่งที่คุณควรใช้วิศวกรเพื่อ...",
  ui_story_5037_50372201_11_dialog_content = "นี่เป็นฉากที่เหลือเชื่อจริงๆ! เมื่อฉันเดินเข้าไป ฉันคิดว่าฉันจะถูกส่งไปที่ Eraveil ด้วยวิธีใดวิธีหนึ่ง!",
  ui_story_5037_50372201_12_dialog_content = "โปรดเชื่อฉันเพื่อน ทุกสิ่งที่ฉันทำเพื่อสนับสนุนความสามารถด้านการแสดงของหญิงสาวคนนี้",
  ui_story_5037_50372201_13_dialog_content = "จริงเหรอ",
  ui_story_5037_50372201_14_dialog_content = "ความรู้ที่แท้จริงได้มาจากการปฏิบัติ เราต้องมีประสบการณ์การแสดงเพื่อรับประสบการณ์การแสดง",
  ui_story_5037_50372201_15_dialog_content = "ฉันเตรียมทั้งฉากและสคริปต์โดยหวังว่าคุณสองคนจะได้สัมผัสความงดงามของการแสดง",
  ui_story_5037_50372201_16_dialog_content = "อัศจรรย์! บางครั้งไอดอลก็ต้องแสดงละครด้วยเช่นกัน",
  ui_story_5037_50372201_17_dialog_content = "ทักษะการแสดงของฉันจะพัฒนาขึ้นอย่างแน่นอนหากได้รับความช่วยเหลือจากมืออาชีพที่มีทักษะ!",
  ui_story_5037_50372201_18_dialog_content = "ในกรณีนี้ เรามาเริ่มกันเลยดีกว่า",
  ui_story_5037_50372201_19_dialog_content = "นี่คือสคริปต์ที่ฉันเตรียม",
  ui_story_5037_50372201_20_dialog_content = "เอ่อ...",
  ui_story_5037_50372201_21_dialog_content = "นี่ไม่ใช่แค่ \"Ada and the Colossus\" แต่มีการเปลี่ยนแปลงบางบรรทัดหรือไม่",
  ui_story_5037_50372201_22_dialog_content = "ถูกตัอง. ฉันตั้งใจเลือกบทละครที่ดัดแปลงมาจากเทพนิยาย",
  ui_story_5037_50372201_23_dialog_content = "เทพนิยายค่อนข้างเรียบง่าย เข้าใจง่าย และมีความท้าทายเล็กน้อยสำหรับนักแสดงมือใหม่",
  ui_story_5037_50372201_24_dialog_content = "คุณคิดทุกอย่าง!",
  ui_story_5037_50372201_25_dialog_content = "แต่แน่นอน. ฉันรู้ว่ามันเป็นอย่างไรที่จะเติบโตจากนักแสดงหน้าใหม่สู่นักแสดงที่มีพรสวรรค์อย่างที่ฉันเป็นในวันนี้!",
