  ui_story_5037_50372201_27_dialog_content = "ตกลง. เนื่องจากฉันคุ้นเคยกับ Colossi ฉันจึงสามารถรับบทเป็น Kaz ได้",
  ui_story_5037_50372201_28_dialog_content = "ฉันจะเล่น Ada แล้ว!",
  ui_story_5037_50372201_29_dialog_content = "เธอเป็นตัวละครที่น่ารักที่อยากรู้อยากเห็นเกี่ยวกับทุกสิ่งและเต็มไปด้วยพลัง",
  ui_story_5037_50372201_30_dialog_content = "ฉันจะรับหน้าที่เป็นผู้บรรยายและส่วนบิตอื่นๆ",
  ui_story_5037_50372201_31_dialog_content = "เมื่อทุกอย่างตัดสินใจแล้ว เราก็เริ่มกันเลยดีกว่า",
  ui_story_5037_50372201_32_dialog_content = "\"ในการโกหก Eraveil ที่สงบสุข ยักษ์ใหญ่ชื่อ Kaz\"",
  ui_story_5037_50372201_33_dialog_content = "\"มันโหยหาท้องฟ้าที่เปิดกว้าง แต่ก็ยังติดอยู่บนพื้นโดยไม่มีผู้นำทาง\"",
  ui_story_5037_50372201_34_dialog_content = "\"แต่ Colossi เกิดมาเพื่อสวรรค์!\"",
  ui_story_5037_50372201_35_dialog_content = "\"อาจมีแบบจำลองที่ดัดแปลงสำหรับบนบกและในทะเล แต่ท้องฟ้ายังคงเป็นบ้านที่แท้จริงของพวกมัน!\"",
  ui_story_5037_50372201_36_dialog_content = "\"ฉันสงสัยว่าการมีเนวิเกเตอร์เป็นอย่างไร... มันต้องดีแค่ไหน...\"",
  ui_story_5037_50372201_37_dialog_content = "\"มีเนวิเกเตอร์ก็เหมือนมีเพื่อนซี้...\"",
  ui_story_5037_50372201_38_dialog_content = "\"หือ? ใครไปที่นั่น? ทำไมคุณถึงพูดกับฉัน ... \"",
  ui_story_5037_50372201_39_dialog_content = "\"มันเป็นภาพลวงตางั้นหรือ ท้ายที่สุดแล้ว ไม่มี Caelesite สักคนที่จะเดินเตร็ดเตร่อยู่รอบๆ ยักษ์ใหญ่ที่ขึ้นสนิมนี้...\"",
  ui_story_5037_50372201_40_dialog_content = "\"และที่นี่ก่อนที่คุณจะยืน Caeleste!\"",
  ui_story_5037_50372201_41_dialog_content = "\"Ada เข้าใกล้ Kaz สังเกตดอกไม้ที่เติบโตทั่วหัวของมัน แล้วเอื้อมมือไปแตะมัน\"",
  ui_story_5037_50372201_42_dialog_content = "(เดี๋ยวก่อน เธอจับหัวมันเหรอ นั่นไม่ได้อยู่ในสคริปต์ของฉัน...)",
  ui_story_5037_50372201_43_dialog_content = "(ฉันควรทำอย่างไร? ไปต่อ?)",
  ui_story_5037_50372201_44_option_content = "ดำเนินการต่อ",
  ui_story_5037_50372201_45_dialog_content = "\"ฉันสัมผัส...\"",
  ui_story_5037_50372201_46_dialog_content = "\"ฮี่ฮี่! เจ้าคิดว่ามันไม่เป็นไรที่ชาวคาเลสจะแอบฟังความคิดส่วนตัวของใครบางคน แล้วเดินเข้าไปแตะมันงั้นเหรอ?\"",
  ui_story_5037_50372201_47_dialog_content = "\"หัวอันงดงามของฉันไม่สามารถถูกใครแตะต้องได้!\"",
  ui_story_5037_50372201_48_dialog_content = "\"แต่มันงดงามและประดับประดาด้วยดอกไม้เล็กๆ น่ารักจริงๆ!\"",
  ui_story_5037_50372201_48X1_dialog_content = "ตัด!",
  ui_story_5037_50372201_49_dialog_content = "ทำได้ดี, PlayerName!",
  ui_story_5037_50372201_50_dialog_content = "หา?",
  ui_story_5037_50372201_51_option_content = "ถามคำถาม",
  ui_story_5037_50372201_52_dialog_content = "รอสักครู่ นั่นไม่ได้อยู่ในสคริปต์",
  ui_story_5037_50372201_52X1_dialog_content = "ตัด!",
  ui_story_5037_50372201_53_dialog_content = "ถูกต้อง",
  ui_story_5037_50372201_54_dialog_content = "ของผมก็ไม่มีเหมือนกัน...",
  ui_story_5037_50372201_55_dialog_content = "เกิดอะไรขึ้นกับสิ่งนี้ ชารอน?",
  ui_story_5037_50372201_56_dialog_content = "การแสดงอาจต้องใช้สคริปต์ แต่ผู้คนเล่นบท",
  ui_story_5037_50372201_57_dialog_content = "เหตุการณ์ไม่คาดฝันอาจเกิดขึ้นได้ในระหว่างการแสดง สคริปต์จะไม่ถูกติดตามไปที่ทีเสมอ",
  ui_story_5037_50372201_58_dialog_content = "นักแสดงที่โดดเด่นจึงต้องสามารถปรับตัวได้ทันสถานการณ์ที่เปลี่ยนไป!",
  ui_story_5037_50372201_59_dialog_content = "อย่างนี้นี่เอง!",
  ui_story_5037_50372201_60_dialog_content = "อย่างแท้จริง! ฉันเคยเห็นละครสองสามเรื่องที่บทพูดบนเวทีแตกต่างจากบทที่เขียนไว้",
  ui_story_5037_50372201_61_dialog_content = "แต่การแสดงด้นสดของนักแสดงก็เป็นธรรมชาติจนไม่มีใครบอกได้!",
  ui_story_5037_50372201_62_dialog_content = "การแสดงด้นสดเป็นทักษะที่สำคัญสำหรับนักแสดง",
  ui_story_5037_50372201_63_dialog_content = "เราต้องเข้าใจอุปนิสัยของตนเองก่อนแล้วจึงกลายเป็นพวกเขา จากนั้นคุณสามารถแสดงออกมาได้อย่างเป็นธรรมชาติที่สุด",
  ui_story_5037_50372201_64_dialog_content = "ฉันเข้าใจแล้ว!",
  ui_story_5037_50372201_65_dialog_content = "ฉันจะทำงานนี้ให้หนักและปรับปรุงความสามารถด้านการแสดงของฉันให้ดียิ่งขึ้นไปอีก!",
