  ui_story_5037_50379901_6_option_content = "บนสะพาน",
  ui_story_5037_50379901_7_dialog_content = "ว้าว นานๆทีจะได้ใส่ชุดนี้ อย่างน้อยก็ยังพอดี!",
  ui_story_5037_50379901_8_dialog_content = "คุณคิดอย่างไร, PlayerName? ระหว่างชุดนี้กับชุดอิลลูมิน่าปกติของฉัน คุณคิดว่าอันไหนดูดีกว่ากัน?",
