  ui_story_5037_50379901_17_dialog_content = "ฮะ? ฉันเห็นเธอในชุดนอน จ้องมองตัวเองอย่างมีความสุขในกระจก...",
  ui_story_5037_50379901_18_dialog_content = "ไม่เห็นอะไรเลย!!!",
