  ui_story_5037_50379901_20_dialog_content = "ถึงกระนั้น ฉันก็ไม่คิดว่าเรื่องแย่ๆ พวกนี้มากพอที่จะทำให้พวกเขาเมินฉันแบบนี้...",
  ui_story_5037_50379901_21_dialog_content = "อ๊าาา! ฉันทำอะไรผิดกันแน่? มันทำให้ฉันบ้า!!",
  ui_story_5037_50379901_22_dialog_content = "ใกล้สิ้นปีแล้วด้วย! เราจะเข้าสู่ปีใหม่ด้วยความอึดอัดระหว่างเราแบบนี้ไม่ได้!",
