  ui_story_5037_50379901_24_dialog_content = "<color=#e8d9bb>ก๊อก ก๊อก ก๊อก!</color>",
  ui_story_5037_50379901_25_dialog_content = "รอง? คาร์ลีน? คุณอยู่ที่นั่น...?",
  ui_story_5037_50379901_26_dialog_content = "<size=33>ฮะ? ฉัน-มัน PlayerName! เอ่อ... เขามาทำอะไรที่นี่ตลอดเวลา?!</size>",
  ui_story_5037_50379901_27_dialog_content = "<size=33>รีบ...!</size>",
  ui_story_5037_50379901_28_dialog_content = "โอ้เฮ้ PlayerName! คุณมาทันเวลาพอดี!",
  ui_story_5037_50379901_29_dialog_content = "คาร์ลีนกับฉันกำลังจะไปหาคุณ เข้ามา!",
  ui_story_5037_50379901_30_dialog_content = "ฮะ? แต่คุณสองคนหลบหน้าฉันมาหลายวันแล้ว! ทัศนคติที่เปลี่ยนไปอย่างกะทันหันคืออะไร?",
  ui_story_5037_50379901_31_dialog_content = "คุณจะรู้ได้เมื่อคุณก้าวเข้าไปข้างใน!",
  ui_story_5037_50379901_32_dialog_content = "เอ่อ... ทำไมไฟดับหมดเลย? ที่นี่มืดมาก...",
  ui_story_5037_50379901_33_dialog_content = "คุณจะได้สัมผัสกับเอฟเฟ็กต์เต็มรูปแบบเมื่อปิดไฟเท่านั้น",
  ui_story_5037_50379901_34_dialog_content = "ท-ผลเต็มๆ ของอะไรนะ?!",
  ui_story_5037_50379901_35_dialog_content = "ตั้งหน้าตั้งตารอ มันเริ่มแล้ว",
  ui_story_5037_50379901_36_dialog_content = "หา?",
  ui_story_5037_50379901_38_dialog_content = "ว้าว... เวลาผ่านไปไวจริงๆ ใช่ไหม?",
  ui_story_5037_50379901_39_dialog_content = "ผ่านไปอีกหนึ่งปีโดยไม่รู้ตัว!",
  ui_story_5037_50379901_40_dialog_content = "แต่การที่รู้สึกได้เร็วขนาดนี้ก็ถือเป็นเรื่องดี",
  ui_story_5037_50379901_41_dialog_content = "หมายความว่าเรามีปีที่มีความหมายมาก",
  ui_story_5037_50379901_42_dialog_content = "ฮ่าๆ ตั้งแต่เราเริ่มผจญภัยกับ PlayerNameทุกวันมีความหมาย!",
  ui_story_5037_50379901_43_dialog_content = "อย่างนั้นเหรอ? แล้วเรามารำลึกความหลังกันไหม?",
  ui_story_5037_50379901_44_dialog_content = "คุณยังจำสถานที่ทั้งหมดที่เราเดินทางไปในปีที่ผ่านมาได้หรือไม่?",
