  ui_story_5037_50379901_46_dialog_content = "ในปีที่ผ่านมา เราฝ่าฟันพายุที่รุนแรงก่อนจะมาถึงนอร์ธแลนด์ในที่สุด...",
  ui_story_5037_50379901_47_dialog_content = "นั่นเป็นครั้งแรกที่ฉันได้เห็นแสงออโรร่าเหนือพระราชวังฤดูหนาวด้วยตาของฉันเอง!",
  ui_story_5037_50379901_48_dialog_content = "นี่เป็นครั้งแรกที่ฉันได้ลองชิมมีทบอลทอดของนอร์ธแลนด์ในซอสสตรอเบอร์รี่ ไม่นึกเลยว่าทั้งสองเข้ากันได้อย่างสมบูรณ์แบบ!",
