  ui_story_5037_50379901_55_dialog_content = "ระหว่างทางกลับจากนอร์ธแลนด์ เราบังเอิญลงจอดในซากปรักหักพังของเมืองโบราณใต้ดิน",
  ui_story_5037_50379901_56_dialog_content = "เพื่อหลีกเลี่ยงการถูกโจมตีโดยหุ่นดรอยด์ของเมือง เราต้องสวมชุดของผู้คนที่เคยอาศัยอยู่ที่นั่น",
  ui_story_5037_50379901_57_dialog_content = "ฮ่าฮ่าฮ่า! ฉันยังจำหน้าตาของ PlayerName ตอนที่เขาต้องใส่ชุดนั้นได้!",
  ui_story_5037_50379901_58_dialog_content = "หลังจากนั้นเราก็พบกับกลุ่มเพื่อนที่ติดอยู่ในเมืองเช่นกัน",
  ui_story_5037_50379901_59_dialog_content = "ในตอนแรก ความแตกต่างของเราทำให้เกิดแต่การทะเลาะกันอย่างต่อเนื่อง...",
  ui_story_5037_50379901_60_dialog_content = "แต่เมื่อทุกคนทำงานร่วมกัน ในที่สุดเราก็สามารถเกลี้ยกล่อมเด็กสาวสองคนที่อาศัยอยู่ในเมืองโบราณได้ในที่สุด...",
  ui_story_5037_50379901_61_dialog_content = "พวกเราทุกคนจึงออกจากเมืองได้อย่างปลอดภัยก่อนที่มันจะถูกทำลายจนหมดสิ้น",
  ui_story_5037_50379901_62_dialog_content = "PlayerName ได้รับข้อความจากเมืองหลังจากที่เรากลับมา!",
  ui_story_5037_50379901_63_dialog_content = "บางทีเราอาจมีโอกาสเยี่ยมชมอีกครั้งสักวันหนึ่ง",
  ui_story_5037_50379901_64_dialog_content = "ใช่... แต่นั่นต้องรอ! เรายังมีสิ่งที่ต้องทำ!",
