  ui_story_5037_50379901_67_dialog_content = "หลังจากมาถึง Koufu-jou เพื่อหางาน เราได้พบกับนักบวชหญิงของเมือง",
  ui_story_5037_50379901_68_dialog_content = "บังเอิญเป็นเทศกาลคาสึกะในตอนนั้นด้วย ดังนั้นทั้งเมืองจึงถูกปกคลุมไปด้วยดอกซากุระสีชมพูสดใส!",
