  ui_story_5037_50379901_75_dialog_content = "เฮ้ เย้! คุณไม่ได้กลับมาที่ลูโมโปลิสในตอนนั้นเหรอ?",
  ui_story_5037_50379901_76_dialog_content = "น-ครั้งหน้า คาร์ลีน! ฉันสัญญาว่าครั้งหน้าเราจะไม่ลืมที่จะเชิญคุณ!",
  ui_story_5037_50379901_77_dialog_content = "เฮ้... เดี๋ยวก่อน! นั่นคือเหตุผลที่คุณไม่ขอให้ฉันมาเมื่อคุณเชิญ PlayerName เพื่อดูการแสดงนั้นใน Lumopolis?!",
  ui_story_5037_50379901_78_dialog_content = "ฉันบอกคุณแล้ว ก็แค่ตามหาเกรเทล",
  ui_story_5037_50379901_79_dialog_content = "เราติดตามเบาะแสไปจนถึงคฤหาสน์แห่งความจริง",
  ui_story_5037_50379901_80_dialog_content = "น่าแปลกที่มันเต็มไปด้วยคนโง่เขลาไร้เหตุผล",
  ui_story_5037_50379901_81_dialog_content = "เชื่อฉัน...",
  ui_story_5037_50379901_82_dialog_content = "คุณควรคิดว่าตัวเองโชคดีที่ไม่ต้องนั่งชมการแสดงนั้น",
  ui_story_5037_50379901_83_dialog_content = "อืม นั่นยิ่งทำให้ฉันอยากรู้มากขึ้นไปอีก!",
  ui_story_5037_50379901_84_dialog_content = "ยังไงก็ตาม รู้สึกเหมือนเราลืมอะไรไปรึเปล่า?",
  ui_story_5037_50379901_85_dialog_content = "คุณหมายถึงตอนนั้นเมื่อ PlayerName ไปทะเลทราย Rediesel? คุณอยู่ที่นั่นด้วยใช่ไหม",
  ui_story_5037_50379901_86_dialog_content = "ใช่แล้ว Blazing Rally! ที่จริงฉันคิด PlayerName ถูกซินซาลักพาตัวไปในตอนนั้น",
  ui_story_5037_50379901_87_dialog_content = "น่าเสียดายที่ฉันไปทันตอนท้ายสุดของการชุมนุมเท่านั้น",
  ui_story_5037_50379901_88_dialog_content = "ส่วน PlayerNameฉันไม่รู้ว่าเขามาอยู่ในที่นั่งผู้โดยสารของรถคันนั้นได้อย่างไร...",
  ui_story_5037_50379901_89_dialog_content = "หรือเรื่องราวในอดีตของ Azure ที่เธอเล่าให้เขาฟัง ตอนนี้ฉันคิดเกี่ยวกับมันแล้ว...",
  ui_story_5037_50379901_90_dialog_content = "ฉันไม่มีรายละเอียดใดๆ",
  ui_story_5037_50379901_91_dialog_content = "แต่สิ่งหนึ่งที่ฉันมั่นใจก็คือบาร์บีคิว Rediesel Desert อร่อยอย่างแน่นอน!",
  ui_story_5037_50379901_92_dialog_content = "ฉันเข้าใจแล้ว... ดูเหมือนว่าปีนี้จะเต็มไปด้วยประสบการณ์การทำอาหารที่แข็งแกร่งมากสำหรับคุณ Vice",
  ui_story_5037_50379901_93_dialog_content = "คุณก็คิดอย่างนั้นเหมือนกัน คาร์ลีน?",
  ui_story_5037_50379901_94_dialog_content = "ฉันรู้ว่าฉันมีความสามารถพิเศษในการทำอาหาร!",
