  ui_story_5037_50379901_106_dialog_content = "โชคดีสำหรับเขา ผู้ลักพาตัวเพียงคนเดียวที่เขาพบเป็นเพียงผู้ฝึกสัตว์มหัศจรรย์",
  ui_story_5037_50379901_107_dialog_content = "สิ่งที่เกิดขึ้นระหว่างการหลบหนีเพียงเล็กน้อยนั้น...",
  ui_story_5037_50379901_108_dialog_content = "เราสามารถอ่านเกี่ยวกับเรื่องนี้ได้ใน \"The Adventures of the Extrozoologist\" เท่านั้น",
  ui_story_5037_50379901_109_dialog_content = "อันที่จริง เฟียเล่าเรื่องการผจญภัยของพวกเขาทั้งหมดให้ฉันฟัง หลายครั้งจริงๆ",
